408	func extractOfficeParts(reader *zip.Reader, parts []string, budget int) (string, error) {
409		if len(parts) == 0 {
410			return "", fmt.Errorf("the archive contains no document body")
411		}
412		var out strings.Builder
413		// One allowance for the whole package, drawn down per part. A fixed budget
414		// per part is not a bound: an archive may hold maxExtractZipEntries parts,
415		// and each could expand to the full cap before the aggregate output check
416		// below ever runs — the same unbounded-aggregate problem the PDF reader
417		// has a document budget for.
418		for _, part := range parts {
419			if budget <= 0 {
420				break
421			}
422			raw, read, err := readZipPart(reader, part, budget)
423			// Charged where the work happened, not where it succeeded. Deducting
424			// only on a part that yields text let a package whose parts each
425			// decompress to the cap and contain none spend the allowance over and
426			// over -- and an over-cap part costs the whole remaining allowance to
427			// discover, so it is charged too.
428			budget -= read
429			if err != nil {
430				// One unreadable note or slide must not lose the whole document.
431				continue
432			}
433			text, err := officeXMLText(raw)
434			if err != nil {
435				continue
436			}
437			if strings.TrimSpace(text) == "" {
438				continue
439			}
440			if out.Len() > 0 {
441				out.WriteString("\n\n")
442			}
443			out.WriteString(text)
444			if out.Len() >= maxExtractOutputBytes {
445				break
446			}
447		}
448		return out.String(), nil
449	}
