18	// Reading the documents a repository keeps that are not code and not markdown.
19	//
20	// A brain indexed .md and nothing else, so the design doc somebody wrote in
21	// Word, the spec that arrived as a PDF and the requirements matrix living in a
22	// spreadsheet were invisible to it — even sitting in `docs/` beside the files it
23	// did read. "We run locally" never explained the absence: these are container
24	// formats with deterministic parsers, they cost no tokens, and Graphify parses
25	// the same set on-device.
26	//
27	// Everything here is standard library. Office files are ZIP archives of XML,
28	// which `archive/zip` and `encoding/xml` read completely; PDF text extraction
29	// lives in docextract_pdf.go and uses `compress/zlib`. That matters because the
30	// install instructions promise no Go toolchain and no C compiler, and a
31	// document reader that needed libxml or tesseract would quietly make those
32	// instructions false.
33	//
34	// The hard part is not parsing. It is refusing to produce plausible garbage: a
35	// scanned PDF has no text layer, an encrypted one cannot be read, and a badly
36	// encoded one yields mojibake that would poison retrieval with text nobody can
37	// search for and no reader can recognise as broken. Every path here either
38	// returns text that passed extractedTextLooksLikeProse or returns an error
39	// naming what went wrong.
40	
41	// Limits. Documents are untrusted input — a 2KB zip can inflate to gigabytes,
42	// and a malformed PDF can describe an enormous stream — so extraction is bounded
43	// before it starts rather than after it hurts.
44	const (
45		maxExtractDocumentBytes = 32 << 20 // 32 MiB of source file
46		maxExtractOutputBytes   = 4 << 20  // 4 MiB of extracted text per document
47		maxExtractZipEntries    = 2048     // an Office file with more parts than this is not a document
48	)
49	
50	// documentFormat is what the extension claims the file is.
51	type documentFormat string
52	
53	const (
54		formatPDF     documentFormat = "pdf"
55		formatDocx    documentFormat = "docx"
56		formatXlsx    documentFormat = "xlsx"
57		formatPptx    documentFormat = "pptx"
58		formatUnknown documentFormat = ""
59	)
60	
61	// documentFormatFor classifies by extension. Content sniffing would be more
62	// robust, but a file named .pdf that is secretly a zip is a file we should
63	// refuse rather than helpfully reinterpret.
64	func documentFormatFor(path string) documentFormat {
65		switch strings.ToLower(filepath.Ext(path)) {
66		case ".pdf":
67			return formatPDF
68		case ".docx":
69			return formatDocx
70		case ".xlsx":
71			return formatXlsx
72		case ".pptx":
73			return formatPptx
74		default:
75			return formatUnknown
76		}
77	}
78	
79	// extractableDocumentExtensions is what this build can read, for help text and
80	// for the selection rule. Legacy .doc/.xls/.ppt are deliberately absent: they
81	// are OLE compound files, an entirely different and much larger problem, and
82	// claiming them here would mean failing on them at ingest time instead.
83	func extractableDocumentExtensions() []string {
84		return []string{".pdf", ".docx", ".xlsx", ".pptx"}
85	}
86	
87	// errNoTextLayer is the honest answer for a document that parsed correctly and
88	// simply contains no text — overwhelmingly a scanned or image-only PDF. It is
89	// separated from a parse failure because the remedy is different: this one needs
90	// OCR, which is out of scope for a dependency-free binary, and saying so beats
91	// indexing an empty document that looks like a successful ingest.
92	type documentExtractionError struct {
93		Path   string
94		Format documentFormat
95		Reason string
96		Remedy string
97	}
98	
99	func (e *documentExtractionError) Error() string {
100		message := fmt.Sprintf("%s: %s", e.Path, e.Reason)
101		if e.Remedy != "" {
102			message += " (" + e.Remedy + ")"
103		}
104		return message
105	}
106	
107	// extractDocumentText reads one document and returns its text.
108	//
109	// data is the file's bytes; the caller has already applied its own size limit,
110	// and this applies its own so a direct caller cannot skip it.
111	func extractDocumentText(path string, data []byte) (string, error) {
112		format := documentFormatFor(path)
113		if format == formatUnknown {
114			return "", &documentExtractionError{
115				Path:   path,
116				Reason: "not a document format this build reads",
117				Remedy: "supported: " + strings.Join(extractableDocumentExtensions(), " "),
118			}
119		}
120		if len(data) == 0 {
121			return "", &documentExtractionError{Path: path, Format: format, Reason: "the file is empty"}
122		}
123		if len(data) > maxExtractDocumentBytes {
124			return "", &documentExtractionError{
125				Path: path, Format: format,
126				Reason: fmt.Sprintf("the file is %d bytes, over the %d-byte extraction limit", len(data), maxExtractDocumentBytes),
127			}
128		}
129	
130		var (
131			text string
132			err  error
133		)
134		switch format {
135		case formatPDF:
136			text, err = extractPDFText(data)
137		case formatDocx:
138			text, err = extractOfficeText(data, docxTextParts)
139		case formatXlsx:
140			text, err = extractXlsxText(data)
141		case formatPptx:
142			text, err = extractPptxText(data)
143		}
144		if err != nil {
145			if _, ok := err.(*documentExtractionError); ok {
146				return "", err
147			}
148			return "", &documentExtractionError{Path: path, Format: format, Reason: err.Error()}
149		}
150	
151		text = normalizeExtractedText(text)
152		if strings.TrimSpace(text) == "" {
153			reason, remedy := "no text was found in the file", ""
154			if format == formatPDF {
155				reason = "the PDF has no text layer"
156				remedy = "it is probably a scan; OCR is out of scope for this build"
157			}
158			return "", &documentExtractionError{Path: path, Format: format, Reason: reason, Remedy: remedy}
159		}
160		// The last gate, and the one that matters most. An extractor that emits
161		// mojibake is worse than one that fails: the failure is visible and the
162		// mojibake silently fills the index with text no query can match.
163		if !extractedTextLooksLikeProse(text) {
164			return "", &documentExtractionError{
165				Path: path, Format: format,
166				Reason: "the extracted text is not readable",
167				Remedy: "the document probably uses an embedded font encoding this build cannot map; convert it to PDF/A or paste the text into a markdown file",
168			}
169		}
170		return text, nil
171	}
172	
173	// normalizeExtractedText makes extractor output safe to store and chunk: real
174	// newlines, no control characters, no runaway blank space, and bounded size.
175	func normalizeExtractedText(text string) string {
176		if !utf8.ValidString(text) {
177			// Latin-1 is the right fallback rather than dropping bytes: Office and
178			// PDF simple encodings are Latin-1-shaped, so this recovers accented
179			// characters instead of turning them into replacement runes.
180			var b strings.Builder
181			for _, c := range []byte(text) {
182				b.WriteRune(rune(c))
183			}
184			text = b.String()
185		}
186		text = strings.ReplaceAll(text, "\r\n", "\n")
187		text = strings.ReplaceAll(text, "\r", "\n")
188	
189		var b strings.Builder
190		b.Grow(len(text))
191		for _, r := range text {
192			switch {
193			case r == '\n' || r == '\t':
194				b.WriteRune(r)
195			case r == utf8.RuneError:
196				// drop
197			case unicode.IsControl(r):
198				// drop: control bytes in a chunk corrupt terminal output and the
199				// stored JSON alike
200			default:
201				b.WriteRune(r)
202			}
203		}
204		text = b.String()
205	
206		lines := strings.Split(text, "\n")
207		trimmed := make([]string, 0, len(lines))
208		blanks := 0
209		for _, line := range lines {
210			line = strings.TrimRight(line, " \t")
211			if strings.TrimSpace(line) == "" {
212				blanks++
213				// A converted document is mostly layout whitespace. More than one
214				// blank line in a row carries no information and costs chunk budget.
215				if blanks > 1 {
216					continue
217				}
218				trimmed = append(trimmed, "")
219				continue
220			}
221			blanks = 0
222			trimmed = append(trimmed, line)
223		}
224		text = strings.TrimSpace(strings.Join(trimmed, "\n"))
225	
226		if len(text) > maxExtractOutputBytes {
227			text = text[:maxExtractOutputBytes]
228			// Cut back to a rune boundary so truncation cannot produce invalid UTF-8.
229			for len(text) > 0 && !utf8.ValidString(text) {
230				text = text[:len(text)-1]
231			}
232			text += "\n\n[truncated]"
233		}
234		return text
235	}
236	
237	// extractedTextLooksLikeProse is the quality gate. It is a heuristic and is
238	// described as one; its job is to catch the specific failure that matters —
239	// a PDF whose font encoding we could not map, which yields long runs of
240	// punctuation and accented bytes that pass every structural check and are
241	// nonetheless unreadable.
242	func extractedTextLooksLikeProse(text string) bool {
243		var letters, digits, spaces, other int
244		for _, r := range text {
245			switch {
246			case unicode.IsLetter(r):
247				letters++
248			case unicode.IsDigit(r):
249				digits++
250			case unicode.IsSpace(r):
251				spaces++
252			default:
253				other++
254			}
255		}
256		total := letters + digits + spaces + other
257		if total == 0 {
258			return false
259		}
260		// A spreadsheet of numbers is legitimate and has few letters, so digits and
261		// spaces count toward "readable" too. What disqualifies a document is a
262		// dominant share of symbols.
263		readable := letters + digits + spaces
264		if float64(readable)/float64(total) < 0.70 {
265			return false
266		}
267		// Mojibake tends to be letter-dense with no word boundaries at all, which
268		// the ratio above happily accepts. Require that a document of any length
269		// actually contains spaces.
270		if total > 200 && spaces == 0 {
271			return false
272		}
273		return true
274	}
