276	// --- Office: ZIP of XML ------------------------------------------------------
277	
278	// officePartSelector decides which parts of an Office package hold text, and in
279	// what order. Returning the order explicitly matters for pptx, where slide10
280	// sorts before slide2 lexically and a reader would get the deck shuffled.
281	type officePartSelector func(names []string) []string
282	
283	func docxTextParts(names []string) []string {
284		var parts []string
285		for _, name := range names {
286			// The body, then footnotes/endnotes. Headers and footers are excluded:
287			// they repeat on every page and would dominate a chunked index with
288			// running titles.
289			if name == "word/document.xml" ||
290				strings.HasPrefix(name, "word/footnotes") ||
291				strings.HasPrefix(name, "word/endnotes") {
292				parts = append(parts, name)
293			}
294		}
295		sort.Slice(parts, func(i, j int) bool {
296			// document.xml first, then the notes.
297			if (parts[i] == "word/document.xml") != (parts[j] == "word/document.xml") {
298				return parts[i] == "word/document.xml"
299			}
300			return parts[i] < parts[j]
301		})
302		return parts
303	}
304	
305	func pptxTextParts(names []string) []string {
306		var slides, notes []string
307		for _, name := range names {
308			switch {
309			case strings.HasPrefix(name, "ppt/slides/slide") && strings.HasSuffix(name, ".xml"):
310				slides = append(slides, name)
311			case strings.HasPrefix(name, "ppt/notesSlides/notesSlide") && strings.HasSuffix(name, ".xml"):
312				notes = append(notes, name)
313			}
314		}
315		sortOfficeNumbered(slides)
316		sortOfficeNumbered(notes)
317		return append(slides, notes...)
318	}
319	
320	// sortOfficeNumbered orders slide2 before slide10. Lexical order would not, and
321	// a deck delivered out of order is a deck whose argument no longer follows.
322	func sortOfficeNumbered(names []string) {
323		sort.Slice(names, func(i, j int) bool {
324			ni, oki := officePartNumber(names[i])
325			nj, okj := officePartNumber(names[j])
326			if oki && okj && ni != nj {
327				return ni < nj
328			}
329			return names[i] < names[j]
330		})
331	}
332	
333	func officePartNumber(name string) (int, bool) {
334		base := strings.TrimSuffix(filepath.Base(name), ".xml")
335		digits := strings.TrimLeftFunc(base, func(r rune) bool { return !unicode.IsDigit(r) })
336		if digits == "" {
337			return 0, false
338		}
339		n, err := strconv.Atoi(digits)
340		return n, err == nil
341	}
342	
343	func openOfficeZip(data []byte) (*zip.Reader, error) {
344		reader, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
345		if err != nil {
346			return nil, fmt.Errorf("not a readable Office file: %w", err)
347		}
348		if len(reader.File) > maxExtractZipEntries {
349			return nil, fmt.Errorf("the archive has %d entries, over the %d-entry limit", len(reader.File), maxExtractZipEntries)
350		}
351		return reader, nil
352	}
353	
354	func officeZipNames(reader *zip.Reader) []string {
355		names := make([]string, 0, len(reader.File))
356		for _, f := range reader.File {
357			names = append(names, f.Name)
358		}
359		return names
360	}
361	
362	// readZipPart decompresses one entry under a hard output cap, so a zip bomb
363	// costs a bounded read rather than the machine's memory.
364	// The second return is how many bytes were decompressed, reported even when the
365	// part is refused: discovering that a part is over the cap costs the whole
366	// remaining allowance, and a caller that charges only on success lets a package
367	// of over-cap parts pay nothing and repeat for every entry it holds.
368	func readZipPart(reader *zip.Reader, name string, budget int) ([]byte, int, error) {
369		for _, f := range reader.File {
370			if f.Name != name {
371				continue
372			}
373			rc, err := f.Open()
374			if err != nil {
375				return nil, 0, err
376			}
377			defer rc.Close()
378			// One byte past the budget, so hitting the cap is distinguishable from
379			// a part that happens to be exactly that size.
380			data, err := io.ReadAll(io.LimitReader(rc, int64(budget)+1))
381			if err != nil {
382				return nil, len(data), err
383			}
384			if len(data) > budget {
385				return nil, len(data), fmt.Errorf("%s expands past the %d-byte limit", name, budget)
386			}
387			return data, len(data), nil
388		}
389		return nil, 0, fmt.Errorf("%s is missing", name)
390	}
391	
392	// extractOfficeText pulls the text out of the selected parts of a WordprocessingML
393	// or PresentationML package.
394	//
395	// Both mark runs of text with a leaf element (w:t, a:t) and paragraphs with a
396	// container (w:p, a:p). Matching on the LOCAL name rather than the namespaced
397	// one is deliberate: the same document is written with different prefixes by
398	// different producers, and a prefix-sensitive reader works on Word's output and
399	// silently returns nothing on LibreOffice's.
400	func extractOfficeText(data []byte, selectParts officePartSelector) (string, error) {
401		reader, err := openOfficeZip(data)
402		if err != nil {
403			return "", err
404		}
405		return extractOfficeParts(reader, selectParts(officeZipNames(reader)), maxExtractOutputBytes)
406	}
407	
408	func extractOfficeParts(reader *zip.Reader, parts []string, budget int) (string, error) {
409		if len(parts) == 0 {
410			return "", fmt.Errorf("the archive contains no document body")
411		}
412		var out strings.Builder
413		// One allowance for the whole package, drawn down per part. A fixed budget
414		// per part is not a bound: an archive may hold maxExtractZipEntries parts,
415		// and each could expand to the full cap before the aggregate output check
416		// below ever runs — the same unbounded-aggregate problem the PDF reader
417		// has a document budget for.
418		for _, part := range parts {
419			if budget <= 0 {
420				break
421			}
422			raw, read, err := readZipPart(reader, part, budget)
423			// Charged where the work happened, not where it succeeded. Deducting
424			// only on a part that yields text let a package whose parts each
425			// decompress to the cap and contain none spend the allowance over and
426			// over -- and an over-cap part costs the whole remaining allowance to
427			// discover, so it is charged too.
428			budget -= read
429			if err != nil {
430				// One unreadable note or slide must not lose the whole document.
431				continue
432			}
433			text, err := officeXMLText(raw)
434			if err != nil {
435				continue
436			}
437			if strings.TrimSpace(text) == "" {
438				continue
439			}
440			if out.Len() > 0 {
441				out.WriteString("\n\n")
442			}
443			out.WriteString(text)
444			if out.Len() >= maxExtractOutputBytes {
445				break
446			}
447		}
448		return out.String(), nil
449	}
450	
451	// officeXMLText walks one XML part and joins its text runs, breaking lines
452	// where the format says a paragraph, row, tab or line break occurs.
453	func officeXMLText(raw []byte) (string, error) {
454		decoder := xml.NewDecoder(bytes.NewReader(raw))
455		// Office XML is well-formed UTF-8; refusing anything else is safer than
456		// guessing a charset from an untrusted document.
457		decoder.Strict = false
458	
459		var (
460			out       bytes.Buffer
461			inText    bool
462			textBuf   strings.Builder
463			cellDepth int
464		)
465		flushParagraph := func() {
466			if out.Len() > 0 && !bytes.HasSuffix(out.Bytes(), []byte("\n")) {
467				out.WriteString("\n")
468			}
469		}
470		for {
471			token, err := decoder.Token()
472			if err == io.EOF {
473				break
474			}
475			if err != nil {
476				// Return what was read rather than nothing: a document truncated
477				// mid-part is still worth more than an empty one.
478				break
479			}
480			switch t := token.(type) {
481			case xml.StartElement:
482				switch t.Name.Local {
483				case "t": // w:t (Word), a:t (PowerPoint), t within si (Excel)
484					inText = true
485					textBuf.Reset()
486				case "tc":
487					cellDepth++
488				case "tab":
489					out.WriteString("\t")
490				case "br", "cr":
491					out.WriteString("\n")
492				}
493			case xml.CharData:
494				if inText {
495					textBuf.Write(t)
496				}
497			case xml.EndElement:
498				switch t.Name.Local {
499				case "t":
500					if inText {
501						out.WriteString(textBuf.String())
502						inText = false
503					}
504				case "p":
505					// Every table cell wraps its text in a paragraph, so breaking
506					// the line here would put each cell of a row on its own line
507					// and destroy the row — which is most of what a table means.
508					// Inside a cell a paragraph is a soft break; outside one it is
509					// the real thing.
510					if cellDepth > 0 {
511						if out.Len() > 0 && !bytes.HasSuffix(out.Bytes(), []byte(" ")) && !bytes.HasSuffix(out.Bytes(), []byte("\t")) {
512							out.WriteString(" ")
513						}
514					} else {
515						flushParagraph()
516					}
517				case "tc":
518					if cellDepth > 0 {
519						cellDepth--
520					}
521					// Separate columns so a row does not run together into one
522					// unreadable word, dropping the soft break the cell's last
523					// paragraph left behind.
524					out.Truncate(len(bytes.TrimRight(out.Bytes(), " ")))
525					out.WriteString("\t")
526				case "tr":
527					// Drop the tab the last cell left, then end the row.
528					out.Truncate(len(bytes.TrimRight(out.Bytes(), " \t")))
529					flushParagraph()
530				}
531			}
532			if out.Len() > maxExtractOutputBytes {
533				break
534			}
535		}
536		return out.String(), nil
537	}
