539	// --- Excel -------------------------------------------------------------------
540	
541	// extractXlsxText reads a workbook sheet by sheet.
542	//
543	// Excel stores most cell text once in a shared-strings table and refers to it by
544	// index from the sheets, so a reader that only walks the sheets finds numbers
545	// and nothing else. The sheet order and names come from the workbook part; a
546	// spreadsheet whose sheets arrive unlabelled and shuffled is much harder to read
547	// than one that says "Sheet: Requirements" above each block.
548	func extractXlsxText(data []byte) (string, error) {
549		reader, err := openOfficeZip(data)
550		if err != nil {
551			return "", err
552		}
553		shared := xlsxSharedStrings(reader)
554	
555		type sheet struct {
556			name string
557			part string
558		}
559		var sheets []sheet
560		for _, name := range xlsxSheetNames(reader) {
561			sheets = append(sheets, sheet{name: name.label, part: name.part})
562		}
563		if len(sheets) == 0 {
564			// No workbook part, or it did not resolve: fall back to every sheet
565			// part in numeric order so a nonstandard producer still yields text.
566			var parts []string
567			for _, n := range officeZipNames(reader) {
568				if strings.HasPrefix(n, "xl/worksheets/sheet") && strings.HasSuffix(n, ".xml") {
569					parts = append(parts, n)
570				}
571			}
572			sortOfficeNumbered(parts)
573			for _, p := range parts {
574				sheets = append(sheets, sheet{name: strings.TrimSuffix(filepath.Base(p), ".xml"), part: p})
575			}
576		}
577		if len(sheets) == 0 {
578			return "", fmt.Errorf("the workbook contains no sheets")
579		}
580	
581		var out strings.Builder
582		// One allowance across every sheet, for the same reason as the other Office
583		// formats: a workbook may declare thousands of sheets.
584		budget := maxExtractOutputBytes
585		for _, s := range sheets {
586			if budget <= 0 {
587				break
588			}
589			raw, read, err := readZipPart(reader, s.part, budget)
590			// An over-cap sheet costs the whole remaining allowance to discover, so
591			// it is charged like a successful read rather than retried free of
592			// charge for every sheet the workbook declares.
593			budget -= read
594			if err != nil {
595				continue
596			}
597			body := xlsxSheetText(raw, shared)
598			if strings.TrimSpace(body) == "" {
599				continue
600			}
601			if out.Len() > 0 {
602				out.WriteString("\n\n")
603			}
604			fmt.Fprintf(&out, "## %s\n", s.name)
605			out.WriteString(body)
606			if out.Len() >= maxExtractOutputBytes {
607				break
608			}
609		}
610		return out.String(), nil
611	}
612	
613	func xlsxSharedStrings(reader *zip.Reader) []string {
614		raw, _, err := readZipPart(reader, "xl/sharedStrings.xml", maxExtractOutputBytes)
615		if err != nil {
616			return nil // a workbook of pure numbers has no shared strings, which is fine
617		}
618		decoder := xml.NewDecoder(bytes.NewReader(raw))
619		decoder.Strict = false
620		var (
621			strs    []string
622			current strings.Builder
623			inItem  bool
624			inText  bool
625		)
626		for {
627			token, err := decoder.Token()
628			if err != nil {
629				break
630			}
631			switch t := token.(type) {
632			case xml.StartElement:
633				switch t.Name.Local {
634				case "si":
635					inItem = true
636					current.Reset()
637				case "t":
638					inText = true
639				}
640			case xml.CharData:
641				// A shared string can be split across several runs (<si><r><t>..),
642				// so append rather than replace or the formatting would eat words.
643				if inItem && inText {
644					current.Write(t)
645				}
646			case xml.EndElement:
647				switch t.Name.Local {
648				case "t":
649					inText = false
650				case "si":
651					strs = append(strs, current.String())
652					inItem = false
653				}
654			}
655		}
656		return strs
657	}
658	
659	type xlsxSheetRef struct {
660		label string
661		part  string
662	}
663	
664	// xlsxSheetNames resolves each sheet's display name to its part path through the
665	// workbook relationships, so blocks come out labelled the way the author named
666	// them rather than as sheet1/sheet2.
667	func xlsxSheetNames(reader *zip.Reader) []xlsxSheetRef {
668		rels := map[string]string{} // rId -> part path
669		if raw, _, err := readZipPart(reader, "xl/_rels/workbook.xml.rels", maxExtractOutputBytes); err == nil {
670			decoder := xml.NewDecoder(bytes.NewReader(raw))
671			decoder.Strict = false
672			for {
673				token, err := decoder.Token()
674				if err != nil {
675					break
676				}
677				start, ok := token.(xml.StartElement)
678				if !ok || start.Name.Local != "Relationship" {
679					continue
680				}
681				var id, target string
682				for _, attr := range start.Attr {
683					switch attr.Name.Local {
684					case "Id":
685						id = attr.Value
686					case "Target":
687						target = attr.Value
688					}
689				}
690				if id == "" || target == "" {
691					continue
692				}
693				target = strings.TrimPrefix(target, "/xl/")
694				target = strings.TrimPrefix(target, "/")
695				if !strings.HasPrefix(target, "xl/") {
696					target = "xl/" + target
697				}
698				rels[id] = target
699			}
700		}
701	
702		raw, _, err := readZipPart(reader, "xl/workbook.xml", maxExtractOutputBytes)
703		if err != nil {
704			return nil
705		}
706		decoder := xml.NewDecoder(bytes.NewReader(raw))
707		decoder.Strict = false
708		var sheets []xlsxSheetRef
709		for {
710			token, err := decoder.Token()
711			if err != nil {
712				break
713			}
714			start, ok := token.(xml.StartElement)
715			if !ok || start.Name.Local != "sheet" {
716				continue
717			}
718			var name, rid string
719			for _, attr := range start.Attr {
720				switch attr.Name.Local {
721				case "name":
722					name = attr.Value
723				case "id": // r:id
724					rid = attr.Value
725				}
726			}
727			part := rels[rid]
728			if part == "" {
729				continue
730			}
731			if name == "" {
732				name = strings.TrimSuffix(filepath.Base(part), ".xml")
733			}
734			sheets = append(sheets, xlsxSheetRef{label: name, part: part})
735		}
736		return sheets
737	}
738	
739	// xlsxSheetText renders one sheet as tab-separated rows, resolving shared-string
740	// cells through the table.
741	func xlsxSheetText(raw []byte, shared []string) string {
742		decoder := xml.NewDecoder(bytes.NewReader(raw))
743		decoder.Strict = false
744		var (
745			out      strings.Builder
746			row      strings.Builder
747			cellType string
748			cells    int
749			column   int
750			inValue  bool
751			inInline bool
752			value    strings.Builder
753		)
754		for {
755			token, err := decoder.Token()
756			if err != nil {
757				break
758			}
759			switch t := token.(type) {
760			case xml.StartElement:
761				switch t.Name.Local {
762				case "row":
763					row.Reset()
764					cells = 0
765				case "c":
766					cellType = ""
767					column = cells + 1
768					for _, attr := range t.Attr {
769						if attr.Name.Local == "t" {
770							cellType = attr.Value
771						}
772						if attr.Name.Local == "r" {
773							if n := xlsxColumnNumber(attr.Value); n > cells {
774								column = n
775							}
776						}
777					}
778					value.Reset()
779				case "v":
780					inValue = true
781				case "is": // inline string, used when shared strings are disabled
782					inInline = true
783				case "t":
784					if inInline {
785						inValue = true
786					}
787				}
788			case xml.CharData:
789				if inValue {
790					value.Write(t)
791				}
792			case xml.EndElement:
793				switch t.Name.Local {
794				case "v", "t":
795					inValue = false
796				case "is":
797					inInline = false
798				case "c":
799					separators := column - cells
800					if cells == 0 {
801						separators--
802					}
803					for j := 0; j < separators; j++ {
804						writeExtractedText(&row, "\t", maxExtractOutputBytes-out.Len())
805					}
806					cells = column
807					writeExtractedText(&row, xlsxCellText(cellType, value.String(), shared), maxExtractOutputBytes-out.Len())
808					if row.Len()+out.Len() >= maxExtractOutputBytes {
809						out.WriteString(row.String())
810						return out.String()
811					}
812				case "row":
813					line := strings.TrimRight(row.String(), "\t")
814					if strings.TrimSpace(line) != "" {
815						out.WriteString(line)
816						writeExtractedText(&out, "\n", maxExtractOutputBytes)
817					}
818				}
819			}
820			if out.Len() > maxExtractOutputBytes {
821				break
822			}
823		}
824		return out.String()
825	}
826	
827	func xlsxCellText(cellType, value string, shared []string) string {
828		if cellType == "s" {
829			index, err := strconv.Atoi(strings.TrimSpace(value))
830			if err != nil || index < 0 || index >= len(shared) {
831				// A dangling index is a corrupt workbook; an empty cell is a more
832				// honest rendering than the raw index, which would read as a number.
833				return ""
834			}
835			return shared[index]
836		}
837		return value
838	}
839	
840	// writeExtractedText enforces the byte cap before an expanding representation
841	// is appended. Keep complete UTF-8 characters when the source is UTF-8.
842	func writeExtractedText(out *strings.Builder, text string, limit int) {
843		remaining := limit - out.Len()
844		if remaining <= 0 {
845			return
846		}
847		if len(text) > remaining {
848			end := remaining
849			for end > 0 && !utf8.RuneStart(text[end]) {
850				end--
851			}
852			text = text[:end]
853		}
854		out.WriteString(text)
855	}
856	
857	// XLSX omits empty cells. Their coordinates preserve the column associations.
858	func xlsxColumnNumber(ref string) int {
859		n := 0
860		for _, c := range ref {
861			if c < 'A' || c > 'Z' {
862				break
863			}
864			n = n*26 + int(c-'A') + 1
865			if n > 16384 {
866				return 0
867			} // Excel's XFD column limit; also bounds overflow.
868		}
869		return n
870	}
