872	func extractPptxText(data []byte) (string, error) {
873		reader, err := openOfficeZip(data)
874		if err != nil {
875			return "", err
876		}
877		names := officeZipNames(reader)
878		hasPresentation := false
879		for _, name := range names {
880			if name == "ppt/presentation.xml" {
881				hasPresentation = true
882			}
883		}
884		if !hasPresentation {
885			return extractOfficeParts(reader, pptxTextParts(names), maxExtractOutputBytes)
886		}
887		budget := maxExtractOutputBytes
888		raw, read, err := readZipPart(reader, "ppt/presentation.xml", budget)
889		budget -= read
890		if err != nil {
891			return "", err
892		}
893		var presentation struct {
894			Slides []struct {
895				Attrs []xml.Attr `xml:",any,attr"`
896			} `xml:"sldIdLst>sldId"`
897		}
898		if err := xml.Unmarshal(raw, &presentation); err != nil {
899			return "", err
900		}
901		raw, read, err = readZipPart(reader, "ppt/_rels/presentation.xml.rels", budget)
902		budget -= read
903		if err != nil {
904			return "", err
905		}
906		var relationships struct {
907			Items []struct {
908				ID     string `xml:"Id,attr"`
909				Target string `xml:"Target,attr"`
910				Mode   string `xml:"TargetMode,attr"`
911			} `xml:"Relationship"`
912		}
913		if err := xml.Unmarshal(raw, &relationships); err != nil {
914			return "", err
915		}
916		targets := map[string]string{}
917		for _, rel := range relationships.Items {
918			if rel.Mode == "External" {
919				continue
920			}
921			target := path.Clean(path.Join("ppt", rel.Target))
922			if strings.HasPrefix(rel.Target, "/") {
923				target = strings.TrimPrefix(path.Clean(rel.Target), "/")
924			}
925			if strings.HasPrefix(target, "ppt/slides/") {
926				targets[rel.ID] = target
927			}
928		}
929		var parts []string
930		for _, slide := range presentation.Slides {
931			for _, attr := range slide.Attrs {
932				if attr.Name.Local == "id" && attr.Name.Space != "" {
933					target := targets[attr.Value]
934					if target == "" {
935						return "", fmt.Errorf("unresolved presentation slide %s", attr.Value)
936					}
937					parts = append(parts, target)
938					break
939				}
940			}
941		}
942		// The presentation's relationship order survives user reordering and
943		// excludes orphan slide parts. Numeric filenames do neither.
944		for _, name := range pptxTextParts(names) {
945			if strings.HasPrefix(name, "ppt/notesSlides/") {
946				parts = append(parts, name)
947			}
948		}
949		return extractOfficeParts(reader, parts, budget)
950	}
