1	package cli
2	
3	import (
4		"bytes"
5		"compress/flate"
6		"compress/zlib"
7		"fmt"
8		"io"
9		"strconv"
10		"strings"
11		"unicode/utf16"
12		"unicode/utf8"
13	)
14	
15	// PDF text extraction, standard library only.
16	//
17	// A PDF does not contain text. It contains instructions for placing glyphs, and
18	// the mapping from the bytes in those instructions back to characters lives in
19	// the font. For a document using a standard encoding the bytes happen to be
20	// Latin-1 and naive extraction works; for one using an embedded subset font
21	// with Identity-H encoding — which is what every modern producer emits — the
22	// bytes are glyph indices and naive extraction yields fluent-looking rubbish.
23	// That is the failure this file is mostly written to avoid: it resolves each
24	// font's /ToUnicode CMap and decodes through it, and where it cannot, the
25	// caller's prose gate rejects the result rather than indexing it.
26	//
27	// Three things are deliberately not attempted. Encrypted PDFs are reported, not
28	// cracked. Scanned PDFs have no text layer at all and are reported as needing
29	// OCR, which a dependency-free binary cannot do. And glyph positions are used
30	// only to decide where lines break — reconstructing multi-column layout from
31	// coordinates is a research problem, and guessing wrong silently interleaves two
32	// columns into nonsense.
33	
34	// pdfObjectKey identifies an indirect object.
35	type pdfObjectKey struct{ number, generation int }
36	
37	type pdfObject struct {
38		dict   map[string]pdfValue
39		stream []byte // raw, still encoded
40	}
41	
42	// pdfValue is a parsed PDF object: one of nil, bool, float64, string (literal),
43	// pdfName, pdfRef, []pdfValue, or map[string]pdfValue.
44	type pdfValue any
45	
46	type pdfName string
47	
48	type pdfRef struct{ number, generation int }
49	
50	const (
51		maxPDFObjects      = 200000
52		maxPDFStreamBytes  = 64 << 20
53		maxPDFContentBytes = 32 << 20
54	
55		// maxPDFTotalDecodedBytes bounds decompression across the WHOLE document,
56		// not just per stream.
57		//
58		// The per-stream cap alone is not a bound: a page tree may hold thousands
59		// of pages, each page's content stream may inflate to the per-stream cap,
60		// and a page that decodes to 32 MiB of drawing operators and almost no text
61		// does not advance the output-size check that ends the loop. A small file
62		// can therefore ask for hundreds of gigabytes of inflation while producing
63		// nothing. Documents are untrusted input, and the work has to be bounded by
64		// what was done rather than by what came out of it.
65		maxPDFTotalDecodedBytes = 256 << 20
66	)
67	
68	// extractPDFText is the entry point. It returns the document's text in reading
69	// order per page, or an error naming why it could not.
70	func extractPDFText(data []byte) (string, error) {
71		return extractPDFTextWithin(data, newPDFDecodeBudget())
72	}
73	
74	// extractPDFTextWithin is extractPDFText with the document-wide decompression
75	// allowance supplied, so a test can set one small enough to be reached.
76	func extractPDFTextWithin(data []byte, budget *pdfDecodeBudget) (string, error) {
77		if !bytes.HasPrefix(bytes.TrimLeft(data[:min(len(data), 1024)], "\x00 \t\r\n"), []byte("%PDF-")) {
78			return "", fmt.Errorf("not a PDF (no %%PDF- header)")
79		}
80		objects := scanPDFObjects(data, budget)
81		if len(objects) == 0 {
82			return "", fmt.Errorf("no PDF objects could be read; the file may be damaged")
83		}
84		if pdfIsEncrypted(data, objects) {
85			return "", fmt.Errorf("the PDF is encrypted; decrypt it first (this build does not carry a cipher for it)")
86		}
87	
88		pages := pdfPages(objects)
89		var out strings.Builder
90		readAnyContent := false
91		for _, page := range pages {
92			if budget.exhausted() {
93				// A short-circuit, not the guard. The guard is in the decoder,
94				// which refuses once the budget is gone, so a document with 20,000
95				// pages would already produce no further text — this just stops
96				// walking them. What was read before the budget ran out is still
97				// the document's text as far as it goes.
98				break
99			}
100			fonts := pdfPageFonts(objects, page, budget)
101			content := pdfPageContent(objects, page, budget)
102			if len(content) == 0 {
103				continue
104			}
105			readAnyContent = true
106			text := pdfContentText(content, fonts)
107			if strings.TrimSpace(text) == "" {
108				continue
109			}
110			if out.Len() > 0 {
111				out.WriteString("\n\n")
112			}
113			out.WriteString(text)
114			if out.Len() > maxExtractOutputBytes {
115				break
116			}
117		}
118		if strings.TrimSpace(out.String()) != "" {
119			return out.String(), nil
120		}
121		// A page tree that WAS readable and produced no text is a real answer — a
122		// scan, or a font this build cannot decode — and the fallback below must
123		// not overturn it. Running it anyway re-reads the same streams without the
124		// font information that made the refusal correct, and hands back the glyph
125		// bytes the page path deliberately withheld. That is the mojibake this
126		// whole file exists to avoid, arriving through the back door.
127		if readAnyContent {
128			return "", nil
129		}
130	
131		// Fallback for a file whose page tree could not be walked — a damaged xref,
132		// a linearized file we mis-scanned, a producer doing something unusual.
133		// Every content-looking stream is read with the union of all ToUnicode maps
134		// in the document. It loses page order and can mix two fonts' encodings, so
135		// it is a last resort rather than the main path; the prose gate decides
136		// whether what comes back is usable.
137		merged, consumed := pdfAllToUnicode(objects, budget)
138		for _, key := range pdfSortedKeys(objects) {
139			object := objects[key]
140			if len(object.stream) == 0 || consumed[key] {
141				continue
142			}
143			content, err := pdfDecodeStreamWithin(objects, object, budget)
144			if err != nil || !bytes.Contains(content, []byte("BT")) {
145				continue
146			}
147			text := pdfContentText(content, map[string]*pdfFont{"": {toUnicode: merged, twoByte: len(merged) > 0}})
148			if strings.TrimSpace(text) == "" {
149				continue
150			}
151			if out.Len() > 0 {
152				out.WriteString("\n\n")
153			}
154			out.WriteString(text)
155			if out.Len() > maxExtractOutputBytes {
156				break
157			}
158		}
159		return out.String(), nil
160	}
161	
162	// --- object scanning ---------------------------------------------------------
163	
164	// scanPDFObjects finds every `N G obj ... endobj` in the file.
165	//
166	// This scans rather than following the cross-reference table, on purpose: a
167	// damaged or unusual xref is the single most common reason a PDF reader gives up
168	// on a file that is otherwise perfectly readable, and the objects themselves are
169	// self-describing. Objects inside object streams (/Type /ObjStm) are expanded
170	// afterwards, because in a modern PDF the page tree usually lives there.
171	func scanPDFObjects(data []byte, budget *pdfDecodeBudget) map[pdfObjectKey]*pdfObject {
172		objects := make(map[pdfObjectKey]*pdfObject)
173		for offset := 0; offset < len(data) && len(objects) < maxPDFObjects; {
174			index := bytes.Index(data[offset:], []byte("obj"))
175			if index < 0 {
176				break
177			}
178			start := offset + index
179			number, generation, ok := pdfObjectHeaderBefore(data, start)
180			offset = start + 3
181			if !ok {
182				continue
183			}
184			body := data[offset:]
185			parser := &pdfParser{data: body}
186			value := parser.parseValue()
187			object := &pdfObject{}
188			if dict, isDict := value.(map[string]pdfValue); isDict {
189				object.dict = dict
190			}
191			parser.skipSpace()
192			if parser.hasPrefix("stream") {
193				parser.pos += len("stream")
194				// The spec allows CRLF or LF after the keyword, never CR alone.
195				if parser.pos < len(body) && body[parser.pos] == '\r' {
196					parser.pos++
197				}
198				if parser.pos < len(body) && body[parser.pos] == '\n' {
199					parser.pos++
200				}
201				object.stream = pdfStreamBytes(objects, object, body[parser.pos:])
202				offset += parser.pos + len(object.stream)
203			} else {
204				offset += parser.pos
205			}
206			objects[pdfObjectKey{number, generation}] = object
207		}
208		expandPDFObjectStreams(objects, budget)
209		return objects
210	}
211	
212	// pdfStreamBytes takes /Length when it is a literal, and otherwise finds
213	// `endstream`. A /Length given as an indirect reference cannot be resolved while
214	// the object map is still being built, which is exactly when many producers use
215	// one — so the search is the normal path, not a fallback.
216	func pdfStreamBytes(objects map[pdfObjectKey]*pdfObject, object *pdfObject, rest []byte) []byte {
217		if length, ok := pdfInt(object.dict["Length"]); ok && length >= 0 && length <= len(rest) {
218			// Trust it only if `endstream` really follows; a stale /Length after an
219			// incremental update would otherwise truncate the stream mid-way.
220			tail := rest[length:]
221			if index := bytes.Index(tail, []byte("endstream")); index >= 0 && index < 4 {
222				return rest[:length]
223			}
224		}
225		index := bytes.Index(rest, []byte("endstream"))
226		if index < 0 {
227			if len(rest) > maxPDFStreamBytes {
228				return rest[:maxPDFStreamBytes]
229			}
230			return rest
231		}
232		end := index
233		// Back off the EOL the writer put before the keyword.
234		for end > 0 && (rest[end-1] == '\n' || rest[end-1] == '\r') {
235			end--
236		}
237		if end > maxPDFStreamBytes {
238			end = maxPDFStreamBytes
239		}
240		return rest[:end]
241	}
242	
243	// pdfObjectHeaderBefore reads the `N G ` that must precede an `obj` keyword.
244	// Without this check the word "obj" inside a stream would be mistaken for the
245	// start of an object.
246	func pdfObjectHeaderBefore(data []byte, objIndex int) (number, generation int, ok bool) {
247		i := objIndex - 1
248		skipSpace := func() {
249			for i >= 0 && (data[i] == ' ' || data[i] == '\r' || data[i] == '\n' || data[i] == '\t') {
250				i--
251			}
252		}
253		readInt := func() (int, bool) {
254			end := i
255			for i >= 0 && data[i] >= '0' && data[i] <= '9' {
256				i--
257			}
258			if end == i {
259				return 0, false
260			}
261			n, err := strconv.Atoi(string(data[i+1 : end+1]))
262			return n, err == nil
263		}
264		skipSpace()
265		if i == objIndex-1 {
266			return 0, 0, false // "obj" must be preceded by whitespace
267		}
268		generation, ok = readInt()
269		if !ok {
270			return 0, 0, false
271		}
272		skipSpace()
273		number, ok = readInt()
274		if !ok {
275			return 0, 0, false
276		}
277		return number, generation, true
278	}
279	
280	// expandPDFObjectStreams parses /Type /ObjStm containers. In a PDF 1.5+ file the
281	// page tree and font dictionaries usually live inside one, so a reader that
282	// ignores them sees a file with streams and no structure.
283	// Object streams decompress before any page is walked, so they have to spend
284	// the same document-wide budget as everything else. Passing nil here made ObjStm
285	// expansion unlimited — each stream capped only at maxPDFContentBytes, up to
286	// maxPDFObjects of them — which is the decompression bomb the budget exists to
287	// stop, reachable before the first page is read.
288	func expandPDFObjectStreams(objects map[pdfObjectKey]*pdfObject, budget *pdfDecodeBudget) {
289		for _, key := range pdfSortedKeys(objects) {
290			object := objects[key]
291			if name, _ := object.dict["Type"].(pdfName); name != "ObjStm" {
292				continue
293			}
294			data, err := pdfDecodeStreamWithin(objects, object, budget)
295			if err != nil {
296				continue
297			}
298			count, _ := pdfInt(object.dict["N"])
299			first, _ := pdfInt(object.dict["First"])
300			if count <= 0 || first <= 0 || first > len(data) {
301				continue
302			}
303			header := &pdfParser{data: data[:first]}
304			type entry struct{ number, offset int }
305			entries := make([]entry, 0, count)
306			for i := 0; i < count; i++ {
307				number, ok1 := pdfInt(header.parseValue())
308				offset, ok2 := pdfInt(header.parseValue())
309				if !ok1 || !ok2 {
310					break
311				}
312				entries = append(entries, entry{number, offset})
313			}
314			for _, e := range entries {
315				at := first + e.offset
316				if at < 0 || at >= len(data) {
317					continue
318				}
319				inner := &pdfParser{data: data[at:]}
320				value := inner.parseValue()
321				dict, isDict := value.(map[string]pdfValue)
322				if !isDict {
323					continue
324				}
325				objectKey := pdfObjectKey{e.number, 0}
326				// A directly-stored object wins over one from a container: it is
327				// what an incremental update would have written.
328				if _, exists := objects[objectKey]; !exists {
329					objects[objectKey] = &pdfObject{dict: dict}
330				}
331			}
332		}
333	}
334	
335	func pdfSortedKeys(objects map[pdfObjectKey]*pdfObject) []pdfObjectKey {
336		keys := make([]pdfObjectKey, 0, len(objects))
337		for key := range objects {
338			keys = append(keys, key)
339		}
340		// Object number order, so output is deterministic across runs — a map walk
341		// would reorder the fallback path's text on every invocation.
342		for i := 1; i < len(keys); i++ {
343			for j := i; j > 0 && (keys[j].number < keys[j-1].number ||
344				(keys[j].number == keys[j-1].number && keys[j].generation < keys[j-1].generation)); j-- {
345				keys[j], keys[j-1] = keys[j-1], keys[j]
346			}
347		}
348		return keys
349	}
350	
351	func pdfResolve(objects map[pdfObjectKey]*pdfObject, value pdfValue) pdfValue {
352		for i := 0; i < 32; i++ { // bounded: a malformed file can make a reference cycle
353			ref, isRef := value.(pdfRef)
354			if !isRef {
355				return value
356			}
357			object, ok := objects[pdfObjectKey{ref.number, ref.generation}]
358			if !ok || object.dict == nil {
359				return nil
360			}
361			value = object.dict
362		}
363		return nil
364	}
365	
366	func pdfIsEncrypted(data []byte, objects map[pdfObjectKey]*pdfObject) bool {
367		// The trailer names /Encrypt. Checking the raw tail as well as the parsed
368		// objects catches files whose trailer we did not turn into an object.
369		tail := data
370		if len(tail) > 4096 {
371			tail = tail[len(tail)-4096:]
372		}
373		if bytes.Contains(tail, []byte("/Encrypt")) {
374			return true
375		}
376		for _, object := range objects {
377			if _, ok := object.dict["Encrypt"]; ok {
378				return true
379			}
380		}
381		return false
382	}
383	
384	// --- filters -----------------------------------------------------------------
385	
386	// pdfDecodeBudget is the document-wide decompression allowance, shared by every
387	// stream decoded while reading one file.
388	type pdfDecodeBudget struct{ remaining int64 }
389	
390	func newPDFDecodeBudget() *pdfDecodeBudget {
391		return &pdfDecodeBudget{remaining: maxPDFTotalDecodedBytes}
392	}
393	
394	// spend reports whether n bytes of decoded output are still affordable. A nil
395	// budget is unlimited, so callers that legitimately have no document context
396	// (tests, one-off decodes) are unaffected.
397	func (b *pdfDecodeBudget) spend(n int) bool {
398		if b == nil {
399			return true
400		}
401		b.remaining -= int64(n)
402		return b.remaining >= 0
403	}
404	
405	func (b *pdfDecodeBudget) exhausted() bool {
406		return b != nil && b.remaining < 0
407	}
408	
409	func pdfDecodeStream(objects map[pdfObjectKey]*pdfObject, object *pdfObject) ([]byte, error) {
410		return pdfDecodeStreamWithin(objects, object, nil)
411	}
412	
413	func pdfDecodeStreamWithin(objects map[pdfObjectKey]*pdfObject, object *pdfObject, budget *pdfDecodeBudget) ([]byte, error) {
414		// The accounting that actually bounds the work is the spend at the end of
415		// this function; refusing up front only avoids inflating one more stream
416		// whose output would be rejected anyway.
417		if budget.exhausted() {
418			return nil, fmt.Errorf("document decompression budget exhausted")
419		}
420		data := object.stream
421		if len(data) == 0 {
422			return nil, fmt.Errorf("empty stream")
423		}
424		filters := pdfFilterNames(objects, object.dict["Filter"])
425		for _, filter := range filters {
426			switch filter {
427			case "FlateDecode", "Fl":
428				decoded, err := pdfInflate(data)
429				if err != nil {
430					return nil, err
431				}
432				data = decoded
433			case "ASCIIHexDecode", "AHx":
434				data = pdfASCIIHexDecode(data)
435			case "ASCII85Decode", "A85":
436				decoded, err := pdfASCII85Decode(data)
437				if err != nil {
438					return nil, err
439				}
440				data = decoded
441			case "DCTDecode", "JPXDecode", "CCITTFaxDecode", "JBIG2Decode":
442				// Images. There is no text in them by definition, and this is the
443				// signature of a scanned page.
444				return nil, fmt.Errorf("image stream (%s)", filter)
445			default:
446				return nil, fmt.Errorf("unsupported filter %s", filter)
447			}
448			if len(data) > maxPDFContentBytes {
449				return nil, fmt.Errorf("stream expands past the %d-byte limit", maxPDFContentBytes)
450			}
451		}
452		if parms := pdfResolve(objects, object.dict["DecodeParms"]); parms != nil {
453			if dict, ok := parms.(map[string]pdfValue); ok {
454				data = pdfApplyPredictor(data, dict)
455				// The per-stream cap above was applied to the filtered bytes; the
456				// predictor runs after it and before the budget is charged, so
457				// without this an expansion here would be paid for by neither.
458				if len(data) > maxPDFContentBytes {
459					return nil, fmt.Errorf("stream expands past the %d-byte limit after predictor", maxPDFContentBytes)
460				}
461			}
462		}
463		if !budget.spend(len(data)) {
464			return nil, fmt.Errorf("document decompression budget exhausted")
465		}
466		return data, nil
467	}
468	
469	func pdfFilterNames(objects map[pdfObjectKey]*pdfObject, value pdfValue) []string {
470		switch v := pdfResolve(objects, value).(type) {
471		case pdfName:
472			return []string{string(v)}
473		case []pdfValue:
474			var names []string
475			for _, item := range v {
476				if name, ok := pdfResolve(objects, item).(pdfName); ok {
477					names = append(names, string(name))
478				}
479			}
480			return names
481		}
482		return nil
483	}
