485	// pdfInflate reads zlib, and falls back to raw deflate. Producers that omit the
486	// two-byte zlib header are not rare, and treating those files as corrupt would
487	// lose documents that every viewer opens.
488	func pdfInflate(data []byte) ([]byte, error) {
489		read := func(r io.Reader) ([]byte, error) {
490			out, err := io.ReadAll(io.LimitReader(r, maxPDFContentBytes+1))
491			if len(out) > maxPDFContentBytes {
492				return nil, fmt.Errorf("stream expands past the %d-byte limit", maxPDFContentBytes)
493			}
494			// A truncated stream still decodes usefully up to the truncation, and
495			// partial text beats no text.
496			if err != nil && len(out) == 0 {
497				return nil, err
498			}
499			return out, nil
500		}
501		if zr, err := zlib.NewReader(bytes.NewReader(data)); err == nil {
502			defer zr.Close()
503			if out, err := read(zr); err == nil && len(out) > 0 {
504				return out, nil
505			}
506		}
507		fr := flate.NewReader(bytes.NewReader(data))
508		defer fr.Close()
509		out, err := read(fr)
510		if err != nil {
511			return nil, fmt.Errorf("stream is not valid Flate data")
512		}
513		return out, nil
514	}
515	
516	func pdfASCIIHexDecode(data []byte) []byte {
517		var out []byte
518		var hi byte
519		var have bool
520		for _, c := range data {
521			var v byte
522			switch {
523			case c >= '0' && c <= '9':
524				v = c - '0'
525			case c >= 'a' && c <= 'f':
526				v = c - 'a' + 10
527			case c >= 'A' && c <= 'F':
528				v = c - 'A' + 10
529			case c == '>':
530				if have {
531					out = append(out, hi<<4)
532				}
533				return out
534			default:
535				continue
536			}
537			if have {
538				out = append(out, hi<<4|v)
539				have = false
540			} else {
541				hi = v
542				have = true
543			}
544		}
545		if have {
546			out = append(out, hi<<4)
547		}
548		return out
549	}
550	
551	func pdfASCII85Decode(data []byte) ([]byte, error) {
552		data = bytes.TrimPrefix(bytes.TrimSpace(data), []byte("<~"))
553		if index := bytes.Index(data, []byte("~>")); index >= 0 {
554			data = data[:index]
555		}
556		var out []byte
557		var group [5]byte
558		n := 0
559		for _, c := range data {
560			switch {
561			case c == 'z' && n == 0:
562				out = append(out, 0, 0, 0, 0)
563				continue
564			case c < '!' || c > 'u':
565				continue
566			}
567			group[n] = c - '!'
568			n++
569			if n == 5 {
570				value := uint32(0)
571				for _, g := range group {
572					value = value*85 + uint32(g)
573				}
574				out = append(out, byte(value>>24), byte(value>>16), byte(value>>8), byte(value))
575				n = 0
576			}
577		}
578		if n > 0 {
579			for i := n; i < 5; i++ {
580				group[i] = 84
581			}
582			value := uint32(0)
583			for _, g := range group {
584				value = value*85 + uint32(g)
585			}
586			full := []byte{byte(value >> 24), byte(value >> 16), byte(value >> 8), byte(value)}
587			out = append(out, full[:n-1]...)
588		}
589		return out, nil
590	}
591	
592	// pdfApplyPredictor undoes PNG row prediction. Streams written with /Predictor
593	// 12 decode to correct-looking bytes that are actually row deltas, so skipping
594	// this step produces plausible garbage rather than an obvious failure.
595	// pdfMaxPredictorColors is the PDF specification's ceiling on colour
596	// components (CMYK). A stream declaring more is malformed, not merely large.
597	const pdfMaxPredictorColors = 4
598	
599	func pdfApplyPredictor(data []byte, parms map[string]pdfValue) []byte {
600		predictor, _ := pdfInt(parms["Predictor"])
601		if predictor < 10 {
602			return data
603		}
604		// Colors, BitsPerComponent and Columns come out of the document, and their
605		// product decides an allocation. The spec bounds the first two — at most
606		// four colour components, and a power-of-two sample size — so a value
607		// outside that is not a stream this reader should try to repair.
608		colors, ok := pdfInt(parms["Colors"])
609		if !ok || colors <= 0 {
610			colors = 1
611		}
612		if colors > pdfMaxPredictorColors {
613			return data
614		}
615		bpc, ok := pdfInt(parms["BitsPerComponent"])
616		if !ok || bpc <= 0 {
617			bpc = 8
618		}
619		switch bpc {
620		case 1, 2, 4, 8, 16:
621		default:
622			return data
623		}
624		columns, ok := pdfInt(parms["Columns"])
625		if !ok || columns <= 0 {
626			columns = 1
627		}
628		bpp := max(1, colors*bpc/8)
629		rowLen := (columns*colors*bpc + 7) / 8
630		// A row longer than everything that was decoded cannot describe it, so this
631		// bounds the allocation by the input rather than by what the file asked
632		// for. It also catches a product large enough to have overflowed.
633		if rowLen <= 0 || rowLen > len(data) {
634			return data
635		}
636		var out []byte
637		previous := make([]byte, rowLen)
638		for offset := 0; offset+1 <= len(data); offset += rowLen + 1 {
639			tag := data[offset]
640			end := min(offset+1+rowLen, len(data))
641			row := make([]byte, end-offset-1)
642			copy(row, data[offset+1:end])
643			for i := range row {
644				var left, up, upLeft byte
645				if i >= bpp {
646					left = row[i-bpp]
647					upLeft = previous[i-bpp]
648				}
649				if i < len(previous) {
650					up = previous[i]
651				}
652				switch tag {
653				case 1:
654					row[i] += left
655				case 2:
656					row[i] += up
657				case 3:
658					row[i] += byte((int(left) + int(up)) / 2)
659				case 4:
660					row[i] += pdfPaeth(left, up, upLeft)
661				}
662			}
663			out = append(out, row...)
664			copy(previous, row)
665		}
666		return out
667	}
668	
669	func pdfPaeth(a, b, c byte) byte {
670		p := int(a) + int(b) - int(c)
671		pa, pb, pc := abs(p-int(a)), abs(p-int(b)), abs(p-int(c))
672		if pa <= pb && pa <= pc {
673			return a
674		}
675		if pb <= pc {
676			return b
677		}
678		return c
679	}
680	
681	func abs(v int) int {
682		if v < 0 {
683			return -v
684		}
685		return v
686	}
