688	// --- pages and fonts ---------------------------------------------------------
689	
690	// pdfPages returns the page dictionaries in document order, walking the page
691	// tree from the catalog and falling back to object order when the tree is
692	// unusable.
693	func pdfPages(objects map[pdfObjectKey]*pdfObject) []map[string]pdfValue {
694		var pages []map[string]pdfValue
695		var walk func(node pdfValue, depth int)
696		seen := map[pdfObjectKey]bool{}
697		walk = func(node pdfValue, depth int) {
698			if depth > 64 || len(pages) > 20000 {
699				return
700			}
701			if ref, isRef := node.(pdfRef); isRef {
702				key := pdfObjectKey{ref.number, ref.generation}
703				if seen[key] { // a /Kids cycle in a malformed file must not hang the reader
704					return
705				}
706				seen[key] = true
707			}
708			dict, ok := pdfResolve(objects, node).(map[string]pdfValue)
709			if !ok {
710				return
711			}
712			switch name, _ := dict["Type"].(pdfName); name {
713			case "Page":
714				pages = append(pages, dict)
715				return
716			case "Pages", "":
717				kids, _ := pdfResolve(objects, dict["Kids"]).([]pdfValue)
718				for _, kid := range kids {
719					walk(kid, depth+1)
720				}
721			}
722		}
723		for _, key := range pdfSortedKeys(objects) {
724			dict := objects[key].dict
725			if name, _ := dict["Type"].(pdfName); name == "Catalog" {
726				walk(dict["Pages"], 0)
727			}
728		}
729		if len(pages) > 0 {
730			return pages
731		}
732		for _, key := range pdfSortedKeys(objects) {
733			dict := objects[key].dict
734			if name, _ := dict["Type"].(pdfName); name == "Page" {
735				pages = append(pages, dict)
736			}
737		}
738		return pages
739	}
740	
741	// pdfPageContent concatenates a page's content streams. /Contents may be one
742	// stream or an array of them, and the array case is not exotic — producers split
743	// a page across streams routinely, and reading only the first loses most of it.
744	func pdfPageContent(objects map[pdfObjectKey]*pdfObject, page map[string]pdfValue, budget *pdfDecodeBudget) []byte {
745		var refs []pdfValue
746		switch v := page["Contents"].(type) {
747		case pdfRef:
748			refs = []pdfValue{v}
749		case []pdfValue:
750			refs = v
751		default:
752			return nil
753		}
754		var out []byte
755		for _, item := range refs {
756			ref, isRef := item.(pdfRef)
757			if !isRef {
758				continue
759			}
760			object, ok := objects[pdfObjectKey{ref.number, ref.generation}]
761			if !ok || len(object.stream) == 0 {
762				continue
763			}
764			decoded, err := pdfDecodeStreamWithin(objects, object, budget)
765			if err != nil {
766				continue
767			}
768			out = append(out, decoded...)
769			out = append(out, '\n')
770			if len(out) > maxPDFContentBytes {
771				break
772			}
773		}
774		return out
775	}
776	
777	// pdfFont is what a content stream needs to turn bytes into characters.
778	type pdfFont struct {
779		toUnicode map[uint32]string
780		twoByte   bool // Identity-H and friends address glyphs with 2-byte codes
781	}
782	
783	// pdfPageFonts resolves /Resources /Font into a map keyed by the name the
784	// content stream uses with Tf.
785	func pdfPageFonts(objects map[pdfObjectKey]*pdfObject, page map[string]pdfValue, budget *pdfDecodeBudget) map[string]*pdfFont {
786		fonts := map[string]*pdfFont{}
787		var resources map[string]pdfValue
788		node := page
789		for depth := 0; node != nil && depth < 64; depth++ {
790			if value, exists := node["Resources"]; exists {
791				resources, _ = pdfResolve(objects, value).(map[string]pdfValue)
792				break
793			}
794			// Resources are inheritable page-tree attributes. The depth bound
795			// handles malformed Parent cycles without recursing.
796			node, _ = pdfResolve(objects, node["Parent"]).(map[string]pdfValue)
797		}
798		if resources == nil {
799			return fonts
800		}
801		fontDict, _ := pdfResolve(objects, resources["Font"]).(map[string]pdfValue)
802		for name, value := range fontDict {
803			dict, ok := pdfResolve(objects, value).(map[string]pdfValue)
804			if !ok {
805				continue
806			}
807			font := &pdfFont{}
808			if encoding, ok := dict["Encoding"].(pdfName); ok {
809				font.twoByte = strings.HasPrefix(string(encoding), "Identity")
810			}
811			if subtype, _ := dict["Subtype"].(pdfName); subtype == "Type0" {
812				// A composite font is multi-byte even when /Encoding is a stream
813				// rather than a name.
814				font.twoByte = true
815			}
816			if ref, isRef := dict["ToUnicode"].(pdfRef); isRef {
817				if object, ok := objects[pdfObjectKey{ref.number, ref.generation}]; ok {
818					// Through the budget: a font is resolved once per page, so a
819					// ToUnicode stream that is a decompression bomb would otherwise
820					// be inflated thousands of times inside a document whose
821					// content streams are properly bounded.
822					if data, err := pdfDecodeStreamWithin(objects, object, budget); err == nil {
823						font.toUnicode = parsePDFToUnicode(data)
824					}
825				}
826			}
827			fonts[name] = font
828		}
829		return fonts
830	}
831	
832	// pdfAllToUnicode merges every ToUnicode map in the document, for the fallback
833	// path where fonts could not be attributed to a page. Conflicting codes resolve
834	// to whichever was seen first, which is a real limitation of that path.
835	// The second return names the streams this consumed. They are CMaps, so they
836	// cannot hold page content, and the fallback scan below must not decode them a
837	// second time: the decode budget is document-wide, and spending it twice on the
838	// same bytes is spent where it matters most — the degraded file that needed the
839	// fallback in the first place.
840	func pdfAllToUnicode(objects map[pdfObjectKey]*pdfObject, budget *pdfDecodeBudget) (map[uint32]string, map[pdfObjectKey]bool) {
841		merged := map[uint32]string{}
842		consumed := map[pdfObjectKey]bool{}
843		for _, key := range pdfSortedKeys(objects) {
844			object := objects[key]
845			if len(object.stream) == 0 {
846				continue
847			}
848			if _, isFont := object.dict["ToUnicode"]; !isFont {
849				// Also accept the CMap stream itself, which names its own type.
850				if name, _ := object.dict["Type"].(pdfName); name != "CMap" {
851					if !bytes.Contains(object.stream[:min(len(object.stream), 64)], []byte("CMap")) {
852						continue
853					}
854				}
855			}
856			data, err := pdfDecodeStreamWithin(objects, object, budget)
857			if err != nil {
858				continue
859			}
860			consumed[key] = true
861			for code, text := range parsePDFToUnicode(data) {
862				if _, exists := merged[code]; !exists {
863					merged[code] = text
864				}
865			}
866		}
867		return merged, consumed
868	}
869	
870	// parsePDFToUnicode reads the bfchar/bfrange sections of a ToUnicode CMap.
871	// This is the piece that makes modern PDFs readable at all: without it a
872	// subset-embedded font's glyph indices are extracted as if they were characters.
873	func parsePDFToUnicode(data []byte) map[uint32]string {
874		out := map[uint32]string{}
875		remaining, entries := maxExtractOutputBytes, 65536
876		add := func(code uint32, text string) bool {
877			// Charge every mapping, including overwritten ones, to bound work as
878			// well as the live map. Decompression limits do not bound CMap expansion.
879			if entries == 0 || len(text) > remaining {
880				return false
881			}
882			entries--
883			remaining -= len(text)
884			out[code] = text
885			return true
886		}
887		text := string(data)
888	
889		for _, section := range pdfCMapSections(text, "beginbfchar", "endbfchar") {
890			parser := &pdfParser{data: []byte(section)}
891			for {
892				parser.skipSpace()
893				if parser.pos >= len(parser.data) {
894					break
895				}
896				src, ok1 := parser.parseValue().(string)
897				dst, ok2 := parser.parseValue().(string)
898				if !ok1 || !ok2 {
899					break
900				}
901				if !add(pdfCodeOf(src), pdfUTF16BEToString(dst)) {
902					return nil
903				}
904			}
905		}
906	
907		for _, section := range pdfCMapSections(text, "beginbfrange", "endbfrange") {
908			parser := &pdfParser{data: []byte(section)}
909			for {
910				parser.skipSpace()
911				if parser.pos >= len(parser.data) {
912					break
913				}
914				lowValue := parser.parseValue()
915				highValue := parser.parseValue()
916				low, ok1 := lowValue.(string)
917				high, ok2 := highValue.(string)
918				if !ok1 || !ok2 {
919					break
920				}
921				parser.skipSpace()
922				lowCode, highCode := pdfCodeOf(low), pdfCodeOf(high)
923				// A range covering the whole code space is a corrupt CMap; refuse
924				// it rather than allocating four billion entries.
925				if highCode < lowCode || highCode-lowCode > 65535 {
926					break
927				}
928				if parser.pos < len(parser.data) && parser.data[parser.pos] == '[' {
929					items, _ := parser.parseValue().([]pdfValue)
930					for i, item := range items {
931						if uint32(i) > highCode-lowCode {
932							break
933						}
934						if s, ok := item.(string); ok {
935							if !add(lowCode+uint32(i), pdfUTF16BEToString(s)) {
936								return nil
937							}
938						}
939					}
940					continue
941				}
942				dst, ok := parser.parseValue().(string)
943				if !ok {
944					break
945				}
946				base := pdfUTF16BEToString(dst)
947				runes := []rune(base)
948				for offset := uint32(0); offset <= highCode-lowCode; offset++ {
949					if len(runes) == 0 {
950						break
951					}
952					// Only the last character advances across a range, per the spec.
953					next := make([]rune, len(runes))
954					copy(next, runes)
955					next[len(next)-1] += rune(offset)
956					if !add(lowCode+offset, string(next)) {
957						return nil
958					}
959				}
960			}
961		}
962		return out
963	}
964	
965	func pdfCMapSections(text, open, close string) []string {
966		var sections []string
967		for {
968			start := strings.Index(text, open)
969			if start < 0 {
970				return sections
971			}
972			text = text[start+len(open):]
973			end := strings.Index(text, close)
974			if end < 0 {
975				sections = append(sections, text)
976				return sections
977			}
978			sections = append(sections, text[:end])
979			text = text[end+len(close):]
980		}
981	}
982	
983	// pdfCodeOf turns the bytes of a CMap source code into an integer. Codes are
984	// written as hex strings and are one or two bytes wide.
985	func pdfCodeOf(s string) uint32 {
986		var code uint32
987		for i := 0; i < len(s) && i < 4; i++ {
988			code = code<<8 | uint32(s[i])
989		}
990		return code
991	}
992	
993	func pdfUTF16BEToString(s string) string {
994		if len(s)%2 != 0 {
995			return s
996		}
997		units := make([]uint16, 0, len(s)/2)
998		for i := 0; i+1 < len(s); i += 2 {
999			units = append(units, uint16(s[i])<<8|uint16(s[i+1]))
1000		}
1001		decoded := string(utf16.Decode(units))
1002		if !utf8.ValidString(decoded) {
1003			return s
1004		}
1005		return decoded
1006	}
