1008	// --- content streams ---------------------------------------------------------
1009	
1010	// pdfContentText walks a decoded content stream and emits the text it draws.
1011	//
1012	// Only the operators that show text or move the cursor matter here. Position is
1013	// used solely to decide where a line ends: a Td/TD/T*/Tm that moves down starts
1014	// a new line, and a large negative kern inside a TJ array is a word space. That
1015	// is enough for prose and deliberately not enough to reconstruct columns.
1016	func pdfContentText(content []byte, fonts map[string]*pdfFont) string {
1017		parser := &pdfParser{data: content}
1018		var (
1019			out      strings.Builder
1020			operands []pdfValue
1021			font     *pdfFont
1022			lastY    float64
1023			haveY    bool
1024		)
1025		newline := func() {
1026			if out.Len() > 0 && out.Len() < maxExtractOutputBytes && !strings.HasSuffix(out.String(), "\n") {
1027				out.WriteByte('\n')
1028			}
1029		}
1030		show := func(value pdfValue) {
1031			s, ok := value.(string)
1032			if !ok {
1033				return
1034			}
1035			writeExtractedText(&out, pdfDecodeShownString(s, font), maxExtractOutputBytes)
1036		}
1037		for out.Len() < maxExtractOutputBytes {
1038			parser.skipSpace()
1039			if parser.pos >= len(parser.data) {
1040				break
1041			}
1042			if operator, ok := parser.parseOperator(); ok {
1043				switch operator {
1044				case "Tf":
1045					font = nil
1046					if len(operands) >= 2 {
1047						if name, ok := operands[len(operands)-2].(pdfName); ok {
1048							font = fonts[string(name)]
1049							if font == nil {
1050								font = fonts[""] // the fallback path's merged map
1051							}
1052						}
1053					}
1054				case "Tj":
1055					if len(operands) >= 1 {
1056						show(operands[len(operands)-1])
1057					}
1058				case "'", "\"":
1059					newline()
1060					if len(operands) >= 1 {
1061						show(operands[len(operands)-1])
1062					}
1063				case "TJ":
1064					if len(operands) >= 1 {
1065						items, _ := operands[len(operands)-1].([]pdfValue)
1066						for _, item := range items {
1067							if out.Len() >= maxExtractOutputBytes {
1068								break
1069							}
1070							switch v := item.(type) {
1071							case string:
1072								show(v)
1073							case float64:
1074								// Kerning is in thousandths of an em, negative to
1075								// move right. Anything past a fifth of an em is a
1076								// space the producer chose not to encode as one.
1077								if v < -200 {
1078									out.WriteByte(' ')
1079								}
1080							}
1081						}
1082					}
1083				case "Td", "TD":
1084					if len(operands) >= 2 {
1085						if dy, ok := pdfFloat(operands[len(operands)-1]); ok && dy != 0 {
1086							newline()
1087						}
1088					}
1089				case "Tm":
1090					if len(operands) >= 6 {
1091						if y, ok := pdfFloat(operands[len(operands)-1]); ok {
1092							if haveY && y != lastY {
1093								newline()
1094							}
1095							lastY, haveY = y, true
1096						}
1097					}
1098				case "T*", "ET":
1099					newline()
1100				}
1101				operands = operands[:0]
1102				continue
1103			}
1104			value := parser.parseValue()
1105			if value == nil && parser.stuck {
1106				parser.pos++ // never spin on a byte we cannot classify
1107				parser.stuck = false
1108				continue
1109			}
1110			operands = append(operands, value)
1111			if len(operands) > 64 {
1112				// Malformed content can pile up operands forever; a real operator
1113				// never takes anywhere near this many.
1114				operands = operands[:0]
1115			}
1116		}
1117		return out.String()
1118	}
