1120	// pdfDecodeShownString turns the bytes of a shown string into characters,
1121	// through the font's ToUnicode map when there is one.
1122	func pdfDecodeShownString(s string, font *pdfFont) string {
1123		if font == nil || len(font.toUnicode) == 0 {
1124			if font != nil && font.twoByte {
1125				// A composite font with no usable ToUnicode: the bytes are glyph
1126				// indices and there is nothing to map them with. Emitting them
1127				// would be mojibake, so emit nothing and let the caller's prose
1128				// gate see an empty or partial document rather than a corrupt one.
1129				return ""
1130			}
1131			return s
1132		}
1133		var b strings.Builder
1134		width := 1
1135		if font.twoByte {
1136			width = 2
1137		}
1138		for i := 0; i+width <= len(s) && b.Len() < maxExtractOutputBytes; i += width {
1139			var code uint32
1140			for j := 0; j < width; j++ {
1141				code = code<<8 | uint32(s[i+j])
1142			}
1143			if text, ok := font.toUnicode[code]; ok {
1144				writeExtractedText(&b, text, maxExtractOutputBytes)
1145				continue
1146			}
1147			// An unmapped code in a font that HAS a ToUnicode map is a glyph the
1148			// producer could not name — typically a ligature it left out of its own
1149			// CMap. The raw byte is a glyph index, not a character, so writing it
1150			// emits something that is certainly wrong ("Cover Le(er"), and runs of
1151			// them can trip the prose gate and lose an otherwise-good document.
1152			// Dropping costs a character and keeps the rest of the word readable.
1153		}
1154		return b.String()
1155	}
