1157	// --- a small PDF object parser ----------------------------------------------
1158	
1159	type pdfParser struct {
1160		data  []byte
1161		pos   int
1162		stuck bool
1163		depth int
1164	}
1165	
1166	func (p *pdfParser) skipSpace() {
1167		for p.pos < len(p.data) {
1168			c := p.data[p.pos]
1169			if c == '%' { // comment to end of line
1170				for p.pos < len(p.data) && p.data[p.pos] != '\n' && p.data[p.pos] != '\r' {
1171					p.pos++
1172				}
1173				continue
1174			}
1175			if c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\f' || c == 0 {
1176				p.pos++
1177				continue
1178			}
1179			return
1180		}
1181	}
1182	
1183	func (p *pdfParser) hasPrefix(s string) bool {
1184		return p.pos+len(s) <= len(p.data) && string(p.data[p.pos:p.pos+len(s)]) == s
1185	}
1186	
1187	func pdfIsDelimiter(c byte) bool {
1188		switch c {
1189		case '(', ')', '<', '>', '[', ']', '{', '}', '/', '%':
1190			return true
1191		}
1192		return false
1193	}
1194	
1195	func pdfIsSpace(c byte) bool {
1196		return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\f' || c == 0
1197	}
1198	
1199	// parseOperator reads a content-stream operator: a bare keyword that is not a
1200	// number, a literal, or one of the object keywords.
1201	func (p *pdfParser) parseOperator() (string, bool) {
1202		p.skipSpace()
1203		start := p.pos
1204		if start >= len(p.data) {
1205			return "", false
1206		}
1207		if c := p.data[start]; c == '\'' || c == '"' {
1208			p.pos++
1209			return string(c), true
1210		}
1211		for p.pos < len(p.data) && !pdfIsSpace(p.data[p.pos]) && !pdfIsDelimiter(p.data[p.pos]) {
1212			p.pos++
1213		}
1214		token := string(p.data[start:p.pos])
1215		if token == "" {
1216			p.pos = start
1217			return "", false
1218		}
1219		switch token {
1220		case "true", "false", "null", "obj", "endobj", "stream", "endstream", "R", "xref", "trailer", "startxref":
1221			p.pos = start
1222			return "", false
1223		}
1224		if c := token[0]; c == '+' || c == '-' || c == '.' || (c >= '0' && c <= '9') {
1225			p.pos = start
1226			return "", false
1227		}
1228		return token, true
1229	}
1230	
1231	func (p *pdfParser) parseValue() pdfValue {
1232		// Arrays and dictionaries recurse through this single entry point. Stop
1233		// parsing a malformed part before nesting can exhaust the Go stack.
1234		if p.depth >= 128 {
1235			p.pos = len(p.data)
1236			return nil
1237		}
1238		p.depth++
1239		defer func() { p.depth-- }()
1240		p.skipSpace()
1241		if p.pos >= len(p.data) {
1242			return nil
1243		}
1244		switch c := p.data[p.pos]; {
1245		case c == '<' && p.hasPrefix("<<"):
1246			return p.parseDict()
1247		case c == '<':
1248			return p.parseHexString()
1249		case c == '(':
1250			return p.parseLiteralString()
1251		case c == '[':
1252			return p.parseArray()
1253		case c == '/':
1254			return p.parseName()
1255		case c == ']' || c == '>' || c == '}' || c == ')':
1256			p.stuck = true
1257			return nil
1258		default:
1259			return p.parseKeywordOrNumber()
1260		}
1261	}
1262	
1263	func (p *pdfParser) parseDict() pdfValue {
1264		p.pos += 2
1265		dict := map[string]pdfValue{}
1266		for {
1267			p.skipSpace()
1268			if p.pos >= len(p.data) {
1269				return dict
1270			}
1271			if p.hasPrefix(">>") {
1272				p.pos += 2
1273				return dict
1274			}
1275			if p.data[p.pos] != '/' {
1276				// Not a key: a malformed dictionary. Step past the offending byte
1277				// rather than looping on it.
1278				p.pos++
1279				continue
1280			}
1281			key, ok := p.parseName().(pdfName)
1282			if !ok {
1283				return dict
1284			}
1285			dict[string(key)] = p.parseValue()
1286		}
1287	}
1288	
1289	func (p *pdfParser) parseArray() pdfValue {
1290		p.pos++
1291		var items []pdfValue
1292		for {
1293			p.skipSpace()
1294			if p.pos >= len(p.data) {
1295				return items
1296			}
1297			if p.data[p.pos] == ']' {
1298				p.pos++
1299				return items
1300			}
1301			before := p.pos
1302			value := p.parseValue()
1303			if p.pos == before {
1304				p.pos++ // guarantee progress
1305				continue
1306			}
1307			if p.stuck {
1308				p.stuck = false
1309				continue
1310			}
1311			items = append(items, value)
1312			if len(items) > 65536 {
1313				return items
1314			}
1315		}
1316	}
1317	
1318	func (p *pdfParser) parseName() pdfValue {
1319		p.pos++ // '/'
1320		var b strings.Builder
1321		for p.pos < len(p.data) {
1322			c := p.data[p.pos]
1323			if pdfIsSpace(c) || pdfIsDelimiter(c) {
1324				break
1325			}
1326			if c == '#' && p.pos+2 < len(p.data) {
1327				if v, err := strconv.ParseUint(string(p.data[p.pos+1:p.pos+3]), 16, 8); err == nil {
1328					b.WriteByte(byte(v))
1329					p.pos += 3
1330					continue
1331				}
1332			}
1333			b.WriteByte(c)
1334			p.pos++
1335		}
1336		return pdfName(b.String())
1337	}
1338	
1339	func (p *pdfParser) parseLiteralString() pdfValue {
1340		p.pos++ // '('
1341		var b strings.Builder
1342		depth := 1
1343		for p.pos < len(p.data) {
1344			c := p.data[p.pos]
1345			p.pos++
1346			switch c {
1347			case '\\':
1348				if p.pos >= len(p.data) {
1349					return b.String()
1350				}
1351				e := p.data[p.pos]
1352				p.pos++
1353				switch e {
1354				case 'n':
1355					b.WriteByte('\n')
1356				case 'r':
1357					b.WriteByte('\r')
1358				case 't':
1359					b.WriteByte('\t')
1360				case 'b':
1361					b.WriteByte('\b')
1362				case 'f':
1363					b.WriteByte('\f')
1364				case '\n':
1365					// A backslash-newline is a line continuation inside the source
1366					// and contributes nothing to the string.
1367				case '\r':
1368					if p.pos < len(p.data) && p.data[p.pos] == '\n' {
1369						p.pos++
1370					}
1371				default:
1372					if e >= '0' && e <= '7' {
1373						value := int(e - '0')
1374						for k := 0; k < 2 && p.pos < len(p.data) && p.data[p.pos] >= '0' && p.data[p.pos] <= '7'; k++ {
1375							value = value*8 + int(p.data[p.pos]-'0')
1376							p.pos++
1377						}
1378						b.WriteByte(byte(value))
1379						continue
1380					}
1381					b.WriteByte(e)
1382				}
1383			case '(':
1384				depth++
1385				b.WriteByte(c)
1386			case ')':
1387				depth--
1388				if depth == 0 {
1389					return b.String()
1390				}
1391				b.WriteByte(c)
1392			default:
1393				b.WriteByte(c)
1394			}
1395		}
1396		return b.String()
1397	}
1398	
1399	func (p *pdfParser) parseHexString() pdfValue {
1400		p.pos++ // '<'
1401		start := p.pos
1402		for p.pos < len(p.data) && p.data[p.pos] != '>' {
1403			p.pos++
1404		}
1405		raw := p.data[start:p.pos]
1406		if p.pos < len(p.data) {
1407			p.pos++
1408		}
1409		return string(pdfASCIIHexDecode(append(raw, '>')))
1410	}
1411	
1412	// parseKeywordOrNumber handles numbers, booleans, null, and the `N G R`
1413	// reference form — which can only be recognised by looking ahead past two
1414	// integers for the R.
1415	func (p *pdfParser) parseKeywordOrNumber() pdfValue {
1416		start := p.pos
1417		for p.pos < len(p.data) && !pdfIsSpace(p.data[p.pos]) && !pdfIsDelimiter(p.data[p.pos]) {
1418			p.pos++
1419		}
1420		token := string(p.data[start:p.pos])
1421		switch token {
1422		case "true":
1423			return true
1424		case "false":
1425			return false
1426		case "null":
1427			return nil
1428		case "":
1429			p.stuck = true
1430			return nil
1431		}
1432		if number, err := strconv.Atoi(token); err == nil {
1433			save := p.pos
1434			p.skipSpace()
1435			genStart := p.pos
1436			for p.pos < len(p.data) && p.data[p.pos] >= '0' && p.data[p.pos] <= '9' {
1437				p.pos++
1438			}
1439			if p.pos > genStart {
1440				generation, _ := strconv.Atoi(string(p.data[genStart:p.pos]))
1441				p.skipSpace()
1442				if p.pos < len(p.data) && p.data[p.pos] == 'R' &&
1443					(p.pos+1 >= len(p.data) || pdfIsSpace(p.data[p.pos+1]) || pdfIsDelimiter(p.data[p.pos+1])) {
1444					p.pos++
1445					return pdfRef{number, generation}
1446				}
1447			}
1448			p.pos = save
1449			return float64(number)
1450		}
1451		if f, err := strconv.ParseFloat(token, 64); err == nil {
1452			return f
1453		}
1454		return pdfName(token) // an unrecognised bare keyword; harmless as an operand
1455	}
1456	
1457	func pdfInt(value pdfValue) (int, bool) {
1458		switch v := value.(type) {
1459		case float64:
1460			return int(v), true
1461		case int:
1462			return v, true
1463		}
1464		return 0, false
1465	}
1466	
1467	func pdfFloat(value pdfValue) (float64, bool) {
1468		if f, ok := value.(float64); ok {
1469			return f, true
1470		}
1471		return 0, false
1472	}
