12	// Fixtures are built here rather than checked in as binaries, so a reader can
13	// see exactly what shape of document each test claims to cover — and so a
14	// fixture cannot quietly stop matching what the test says it is.
15	
16	func zipFile(t *testing.T, parts map[string]string) []byte {
17		t.Helper()
18		buf := &bytes.Buffer{}
19		w := zip.NewWriter(buf)
20		// Deterministic order so a failure is reproducible.
21		for _, name := range sortedKeys(parts) {
22			f, err := w.Create(name)
23			if err != nil {
24				t.Fatalf("create %s: %v", name, err)
25			}
26			if _, err := f.Write([]byte(parts[name])); err != nil {
27				t.Fatalf("write %s: %v", name, err)
28			}
29		}
30		if err := w.Close(); err != nil {
31			t.Fatalf("close zip: %v", err)
32		}
33		return buf.Bytes()
34	}
35	
36	func sortedKeys(m map[string]string) []string {
37		keys := make([]string, 0, len(m))
38		for k := range m {
39			keys = append(keys, k)
40		}
41		for i := 1; i < len(keys); i++ {
42			for j := i; j > 0 && keys[j] < keys[j-1]; j-- {
43				keys[j], keys[j-1] = keys[j-1], keys[j]
44			}
45		}
46		return keys
47	}
