49	// docxFixture builds a WordprocessingML document. The namespace prefix is `w:`
50	// here and deliberately varied in one test, because a reader that matches on the
51	// prefix rather than the local name works on Word and silently returns nothing
52	// on other producers.
53	func docxFixture(t *testing.T, bodyXML string) []byte {
54		t.Helper()
55		return zipFile(t, map[string]string{
56			"[Content_Types].xml": `<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"/>`,
57			"word/document.xml": `<?xml version="1.0"?>` +
58				`<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">` +
59				`<w:body>` + bodyXML + `</w:body></w:document>`,
60		})
61	}
