1	package cli
2	
3	import (
4		"archive/zip"
5		"bytes"
6		"compress/zlib"
7		"fmt"
8		"strings"
9		"testing"
10	)
11	
12	// Fixtures are built here rather than checked in as binaries, so a reader can
13	// see exactly what shape of document each test claims to cover — and so a
14	// fixture cannot quietly stop matching what the test says it is.
15	
16	func zipFile(t *testing.T, parts map[string]string) []byte {
17		t.Helper()
18		buf := &bytes.Buffer{}
19		w := zip.NewWriter(buf)
20		// Deterministic order so a failure is reproducible.
21		for _, name := range sortedKeys(parts) {
22			f, err := w.Create(name)
23			if err != nil {
24				t.Fatalf("create %s: %v", name, err)
25			}
26			if _, err := f.Write([]byte(parts[name])); err != nil {
27				t.Fatalf("write %s: %v", name, err)
28			}
29		}
30		if err := w.Close(); err != nil {
31			t.Fatalf("close zip: %v", err)
32		}
33		return buf.Bytes()
34	}
35	
36	func sortedKeys(m map[string]string) []string {
37		keys := make([]string, 0, len(m))
38		for k := range m {
39			keys = append(keys, k)
40		}
41		for i := 1; i < len(keys); i++ {
42			for j := i; j > 0 && keys[j] < keys[j-1]; j-- {
43				keys[j], keys[j-1] = keys[j-1], keys[j]
44			}
45		}
46		return keys
47	}
48	
49	// docxFixture builds a WordprocessingML document. The namespace prefix is `w:`
50	// here and deliberately varied in one test, because a reader that matches on the
51	// prefix rather than the local name works on Word and silently returns nothing
52	// on other producers.
53	func docxFixture(t *testing.T, bodyXML string) []byte {
54		t.Helper()
55		return zipFile(t, map[string]string{
56			"[Content_Types].xml": `<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"/>`,
57			"word/document.xml": `<?xml version="1.0"?>` +
58				`<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">` +
59				`<w:body>` + bodyXML + `</w:body></w:document>`,
60		})
61	}
62	
63	func docxParagraph(runs ...string) string {
64		var b strings.Builder
65		b.WriteString("<w:p>")
66		for _, run := range runs {
67			fmt.Fprintf(&b, "<w:r><w:t>%s</w:t></w:r>", run)
68		}
69		b.WriteString("</w:p>")
70		return b.String()
71	}
