73	// --- PDF construction --------------------------------------------------------
74	
75	// pdfBuilder assembles a syntactically real PDF: numbered indirect objects, a
76	// catalog, a page tree and a cross-reference table. Tests that hand-wrote a
77	// fragment would prove only that the parser reads that fragment.
78	type pdfBuilder struct {
79		objects []string
80	}
81	
82	func (b *pdfBuilder) add(body string) int {
83		b.objects = append(b.objects, body)
84		return len(b.objects)
85	}
86	
87	// addStream adds a Flate-compressed stream object, which is how every real
88	// producer writes content.
89	func (b *pdfBuilder) addStream(t *testing.T, dictExtra, content string) int {
90		t.Helper()
91		buf := &bytes.Buffer{}
92		zw := zlib.NewWriter(buf)
93		if _, err := zw.Write([]byte(content)); err != nil {
94			t.Fatalf("compress: %v", err)
95		}
96		if err := zw.Close(); err != nil {
97			t.Fatalf("close: %v", err)
98		}
99		compressed := buf.String()
100		return b.add(fmt.Sprintf("<< /Length %d /Filter /FlateDecode %s >>\nstream\n%s\nendstream",
101			len(compressed), dictExtra, compressed))
102	}
103	
104	func (b *pdfBuilder) build() []byte {
105		var out bytes.Buffer
106		out.WriteString("%PDF-1.7\n")
107		offsets := make([]int, len(b.objects)+1)
108		for i, body := range b.objects {
109			offsets[i+1] = out.Len()
110			fmt.Fprintf(&out, "%d 0 obj\n%s\nendobj\n", i+1, body)
111		}
112		xref := out.Len()
113		fmt.Fprintf(&out, "xref\n0 %d\n0000000000 65535 f \n", len(b.objects)+1)
114		for i := 1; i <= len(b.objects); i++ {
115			fmt.Fprintf(&out, "%010d 00000 n \n", offsets[i])
116		}
117		fmt.Fprintf(&out, "trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n", len(b.objects)+1, xref)
118		return out.Bytes()
119	}
120	
121	// simplePDF is a one-page document in a font with no ToUnicode map, where the
122	// string bytes are the characters.
123	func simplePDF(t *testing.T, content string) []byte {
124		t.Helper()
125		b := &pdfBuilder{}
126		b.add("<< /Type /Catalog /Pages 2 0 R >>")                                                      // 1
127		b.add("<< /Type /Pages /Kids [3 0 R] /Count 1 >>")                                              // 2
128		b.add("<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>") // 3
129		b.addStream(t, "", content)                                                                     // 4
130		b.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")                                 // 5
131		return b.build()
132	}
133	
134	// identityHPDF is the modern case: a composite font addressed with two-byte
135	// glyph codes, readable only through its /ToUnicode CMap. `codes` are the raw
136	// two-byte codes drawn; `cmap` is the CMap body mapping them back.
137	func identityHPDF(t *testing.T, codes string, cmapBody string) []byte {
138		t.Helper()
139		b := &pdfBuilder{}
140		b.add("<< /Type /Catalog /Pages 2 0 R >>")
141		b.add("<< /Type /Pages /Kids [3 0 R] /Count 1 >>")
142		b.add("<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>")
143		b.addStream(t, "", "BT /F1 12 Tf ("+codes+") Tj ET")
144		b.add("<< /Type /Font /Subtype /Type0 /BaseFont /AAAAAA+Test /Encoding /Identity-H /ToUnicode 6 0 R >>")
145		b.addStream(t, "", `/CIDInit /ProcSet findresource begin
146	begincmap
147	/CMapName /Adobe-Identity-UCS def
148	/CMapType 2 def
149	1 begincodespacerange
150	<0000><FFFF>
151	endcodespacerange
152	`+cmapBody+`
153	endcmap
154	end`)
155		return b.build()
156	}
