11	// What these tests are for.
12	//
13	// An extractor has two ways to fail and only one of them is visible. It can
14	// refuse a document it should have read, which somebody notices; or it can
15	// return text that looks fine and is wrong, which nobody notices until a search
16	// quietly stops finding things. Most of what follows is about the second kind:
17	// the Identity-H case where bytes are glyph indices, the shared-strings case
18	// where a spreadsheet reads as numbers with no labels, the scanned PDF that
19	// would otherwise be indexed as an empty document and counted as a success.
20	
21	// --- Word --------------------------------------------------------------------
22	
23	func TestDocxReadsParagraphsAndRuns(t *testing.T) {
24		// Word splits a sentence across runs whenever formatting changes, so a
25		// reader that takes one run per paragraph loses most of the words in any
26		// document that has bold in it.
27		data := docxFixture(t,
28			docxParagraph("The retry policy ", "backs off ", "exponentially.")+
29				docxParagraph("Second paragraph."))
30	
31		text, err := extractDocumentText("spec.docx", data)
32		if err != nil {
33			t.Fatalf("extract: %v", err)
34		}
35		if !strings.Contains(text, "The retry policy backs off exponentially.") {
36			t.Fatalf("runs were not joined into a sentence: %q", text)
37		}
38		if !strings.Contains(text, "Second paragraph.") {
39			t.Fatalf("the second paragraph is missing: %q", text)
40		}
41		// Paragraphs are separate lines, or every document arrives as one wall of
42		// text and chunking has nothing to cut on.
43		if !strings.Contains(text, "exponentially.\nSecond") {
44			t.Fatalf("paragraphs were not separated: %q", text)
45		}
46	}
