246	func TestPDFRefusesRatherThanEmitGlyphIndices(t *testing.T) {
247		// A composite font with no usable ToUnicode cannot be decoded. Emitting the
248		// bytes would produce fluent-looking rubbish that passes into the index and
249		// can never be searched for; the honest outcome is a named failure.
250		b := &pdfBuilder{}
251		b.add("<< /Type /Catalog /Pages 2 0 R >>")
252		b.add("<< /Type /Pages /Kids [3 0 R] /Count 1 >>")
253		b.add("<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>")
254		// Printable glyph indices on purpose. Indices that happen to be control
255		// bytes would be stripped by normalization anyway, so a test using those
256		// would pass even with this guard deleted — it has to be the case where
257		// emitting the bytes produces convincing-looking letters.
258		b.addStream(t, "", "BT /F1 12 Tf (Hello there, this reads like English) Tj ET")
259		b.add("<< /Type /Font /Subtype /Type0 /BaseFont /AAAAAA+NoMap /Encoding /Identity-H >>")
260	
261		text, err := extractDocumentText("nomap.pdf", b.build())
262		if err == nil {
263			t.Fatalf("an unmappable composite font was reported as successfully extracted: %q", text)
264		}
