266			t.Fatalf("glyph bytes leaked into the output: %v", err)
267		}
268		if !strings.Contains(err.Error(), "no text layer") && !strings.Contains(err.Error(), "not readable") {
269			t.Fatalf("the error should say the text could not be read: %v", err)
270		}
271	}
