368	func TestExtractionRejectsUnreadableOutput(t *testing.T) {
369		// The gate exists because a broken font encoding produces text that passes
370		// every structural check and is nonetheless unsearchable. Indexing it is
371		// worse than failing, because the failure is invisible.
372		if extractedTextLooksLikeProse(strings.Repeat("@#$%^&*(){}", 60)) {
373			t.Fatal("a wall of symbols was accepted as readable text")
374		}
375		if extractedTextLooksLikeProse(strings.Repeat("abcdefgh", 40)) {
376			t.Fatal("a long run with no word boundaries at all was accepted")
377		}
378		// And it must not reject the legitimate documents it sits in front of.
379		for name, sample := range map[string]string{
380			"prose":       "The retry policy backs off exponentially, capped at thirty seconds.",
381			"spreadsheet": "Latency\t200\t300\nThroughput\t1500\t1800\n",
382			"code-ish":    "func retry(ctx context.Context) error { return backoff(ctx) }",
383			"accented":    "La révision précédente utilisait une stratégie différente.",
384		} {
385			if !extractedTextLooksLikeProse(sample) {
386				t.Fatalf("%s was rejected as unreadable: %q", name, sample)
387			}
388		}
389	}
390	
391	// The predicate above is unit-tested; this drives a whole document through the
392	// real entry point, because a gate that exists and is never called is the same
393	// as no gate. The content is a page of symbols — the shape a mis-decoded font
394	// produces — and it must not reach the caller as text.
395	func TestExtractionAppliesTheProseGateToWholeDocuments(t *testing.T) {
396		garbage := strings.Repeat(`\(\)#$%^&*{}[]<>|~`+"`", 80)
397		data := simplePDF(t, "BT /F1 12 Tf ("+garbage+") Tj ET")
398	
399		text, err := extractDocumentText("mojibake.pdf", data)
400		if err == nil {
401			t.Fatalf("an unreadable document was accepted: %q", text)
402		}
403		if !strings.Contains(err.Error(), "not readable") {
404			t.Fatalf("the error should say the text is unreadable: %v", err)
405		}
406		// And it must suggest something to do about it.
407		if !strings.Contains(err.Error(), "encoding") {
408			t.Fatalf("the error should explain the likely cause: %v", err)
409		}
410	}
