508	func TestMalformedInputTerminates(t *testing.T) {
509		// A damaged or hostile document must not hang the ingest. These are the
510		// shapes that make a hand-written parser spin: unterminated containers,
511		// truncated streams, and dictionaries that never close.
512		for name, data := range map[string][]byte{
513			"unterminated array":  []byte("%PDF-1.7\n1 0 obj\n[[[[[[[[[[\nendobj\n"),
514			"unterminated dict":   []byte("%PDF-1.7\n1 0 obj\n<< /A << /B << /C\nendobj\n"),
515			"unterminated string": []byte("%PDF-1.7\n1 0 obj\n<< /Length 5 >>\nstream\n(((((\n"),
516			"stream, no end":      []byte("%PDF-1.7\n1 0 obj\n<< >>\nstream\nBT /F1 12 Tf (x) Tj ET\n"),
517			"obj with no header":  []byte("%PDF-1.7\nobj obj obj obj\n"),
518			"nul bytes":           append([]byte("%PDF-1.7\n"), make([]byte, 4096)...),
519			"header only":         []byte("%PDF-1.7\n"),
520		} {
521			done := make(chan struct{})
522			go func() {
523				defer close(done)
524				defer func() {
