548			"word/document.xml": "<w:document><w:body><w:p><w:r><w:t>Opening line.</w:t></w:r></w:p></w:body></w:document>",
549			"word/footnotes99.xml": "<w:document><w:body><w:p><w:r><w:t>SENTINEL past the allowance.</w:t></w:r>" +
550				"</w:p></w:body></w:document>",
551		}
552		for i := 0; i < 10; i++ {
553			parts[fmt.Sprintf("word/endnotes%02d.xml", i)] = filler
554		}
555	
556		text, err := extractDocumentText("big.docx", zipFile(t, parts))
557		if err != nil {
558			t.Fatalf("extract: %v", err)
559		}
560		if !strings.Contains(text, "Opening line.") {
561			t.Fatalf("the body was lost entirely: %q", text)
562		}
563		if strings.Contains(text, "SENTINEL") {
564			t.Fatal("textless parts spent none of the allowance, so the walk ran past it")
565		}
566	}
