395	// A per-stream cap is not a bound on a document. Thousands of pages, each
396	// inflating to the per-stream cap and producing almost no text, advance nothing
397	// that ends the loop — so a small file can ask for an unbounded amount of
398	// decompression work.
399	func TestPDFDecompressionIsBoundedAcrossTheWholeDocument(t *testing.T) {
400		t.Parallel()
401		budget := newPDFDecodeBudget()
402		if !budget.spend(maxPDFTotalDecodedBytes / 2) {
403			t.Fatal("half the budget was refused")
404		}
405		if budget.exhausted() {
406			t.Fatal("the budget reported exhaustion with half of it left")
407		}
408		if budget.spend(maxPDFTotalDecodedBytes) {
409			t.Fatal("a spend past the document budget was allowed")
410		}
411		if !budget.exhausted() {
412			t.Fatal("the budget did not record exhaustion")
413		}
414		// A nil budget is unlimited, so callers with no document context are
415		// unaffected rather than silently capped at zero.
416		var none *pdfDecodeBudget
417		if !none.spend(1 << 30) {
418			t.Fatal("a nil budget refused a spend")
419		}
420		if none.exhausted() {
421			t.Fatal("a nil budget reported exhaustion")
422		}
423	}
