425	func TestPDFStopsReadingPagesOnceTheBudgetIsGone(t *testing.T) {
426		t.Parallel()
427		// A per-stream cap is not a bound on a document: thousands of pages, each
428		// inflating to that cap and producing almost no text, advance nothing that
429		// ends the loop. The budget is what ends it, and this proves the loop
430		// actually consults it by giving it one too small to finish the document.
431		const pages = 20
432		// Each page carries a distinct sentence and a lot of drawing operators, so
433		// pages that were read are identifiable and decoded bytes far exceed text.
434		filler := strings.Repeat("1 0 0 1 0 0 cm ", 4000)
435		b := &pdfBuilder{}
436		b.add("<< /Type /Catalog /Pages 2 0 R >>")
437		kids := make([]string, 0, pages)
438		for i := 0; i < pages; i++ {
439			kids = append(kids, fmt.Sprintf("%d 0 R", 3+i*2))
440		}
441		b.add(fmt.Sprintf("<< /Type /Pages /Kids [%s] /Count %d >>", strings.Join(kids, " "), pages))
442		for i := 0; i < pages; i++ {
443			b.add(fmt.Sprintf("<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 %d 0 R >> >> /Contents %d 0 R >>",
444				3+pages*2, 4+i*2))
445			b.addStream(t, "", fmt.Sprintf("q %s Q BT /F1 12 Tf (Sentence number %d appears here.) Tj ET", filler, i))
446		}
447		b.add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")
448		data := b.build()
449	
450		full, err := extractPDFTextWithin(data, newPDFDecodeBudget())
451		if err != nil {
452			t.Fatalf("unbounded extraction: %v", err)
453		}
454		fullPages := strings.Count(full, "appears here.")
455		if fullPages != pages {
456			t.Fatalf("the fixture is wrong: %d of %d pages read with a full budget", fullPages, pages)
457		}
458	
459		// A budget that runs out partway through the document.
460		small := &pdfDecodeBudget{remaining: int64(len(filler))}
461		limited, err := extractPDFTextWithin(data, small)
462		if err != nil {
463			t.Fatalf("bounded extraction: %v", err)
464		}
465		limitedPages := strings.Count(limited, "appears here.")
466		if limitedPages >= fullPages {
467			t.Fatalf("the budget did not stop the page loop: %d of %d pages still read", limitedPages, fullPages)
468		}
469		if !small.exhausted() {
470			t.Fatal("the budget was never spent; decompression is not being accounted for")
471		}
472	}
