474	// A font is resolved once per page, so a /ToUnicode stream that is a
475	// decompression bomb would be inflated once per page — thousands of times
476	// inside a document whose content streams are properly bounded. Font streams
477	// have to spend from the same allowance.
478	func TestFontStreamsSpendFromTheDocumentBudget(t *testing.T) {
479		t.Parallel()
480		b := &pdfBuilder{}
