482		b.add("<< /Type /Pages /Kids [3 0 R] /Count 1 >>")
483		b.add("<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>")
484		b.addStream(t, "", "BT /F1 12 Tf (x) Tj ET")
485		b.add("<< /Type /Font /Subtype /Type0 /BaseFont /AAAAAA+Test /Encoding /Identity-H /ToUnicode 6 0 R >>")
486		// A large, highly compressible ToUnicode stream.
487		b.addStream(t, "", "begincmap\n"+strings.Repeat("% filler filler filler filler\n", 20000)+"endcmap\n")
488		data := b.build()
