496		budget := newPDFDecodeBudget()
497		before := budget.remaining
498		pdfPageFonts(objects, pages[0], budget)
499		if budget.remaining == before {
500			t.Fatal("resolving a font's ToUnicode stream spent nothing from the document budget")
501		}
