606	// Extractable documents return early from inspectSeedFile to skip the NUL-byte
607	// check — every PDF and Office file fails it by construction — and that early
608	// return also skipped the content hash, so editing a PDF under docs/ left the
609	// fingerprint identical and the packet looked fresh when it was not.
610	func TestEditingAnExtractableDocumentChangesItsHash(t *testing.T) {
611		t.Parallel()
612		repoDir := t.TempDir()
613		if err := os.MkdirAll(filepath.Join(repoDir, "docs"), 0o755); err != nil {
614			t.Fatal(err)
615		}
616		path := filepath.Join(repoDir, "docs", "spec.pdf")
617	
618		write := func(text string) seedFileIndexEntry {
619			if err := os.WriteFile(path, simplePDF(t, "BT /F1 12 Tf ("+text+") Tj ET"), 0o644); err != nil {
620				t.Fatal(err)
621			}
622			return inspectSeedFile(repoDir, "docs/spec.pdf", seedCommandOptions{maxFileBytes: 1 << 20})
623		}
