625		before := write("The retry budget is thirty seconds.")
626		if !before.Included {
627			t.Fatalf("the PDF was excluded as %q", before.Reason)
628		}
629		if before.Hash == "" {
630			t.Fatal("an included document carries no content hash, so the fingerprint cannot move with it")
631		}
