646	// The fallback scan and the ToUnicode merge both walk every stream. The merge
647	// runs first and decodes the CMap streams; the scan must not decode them again,
648	// because the decode budget is document-wide and this is the path taken by the
649	// degraded files where it is most likely to bind.
650	//
651	// The document below has no page tree, so the page path yields nothing and the
652	// fallback runs — with a CMap stream present for it to re-decode.
653	func TestPDFFallbackDoesNotDecodeCMapStreamsTwice(t *testing.T) {
654		t.Parallel()
655		b := &pdfBuilder{}
656		b.add("<< /Type /Catalog >>") // no /Pages: forces the fallback
657		b.addStream(t, "/Type /CMap", strings.Repeat("begincmap endcmap\n", 400))
658		b.addStream(t, "", "BT /F1 12 Tf (The retry budget is thirty seconds.) Tj ET")
659		pdf := b.build()
660	
661		full := &pdfDecodeBudget{remaining: 1 << 20}
662		text, err := extractPDFTextWithin(pdf, full)
663		if err != nil || !strings.Contains(text, "retry budget") {
664			t.Skipf("this document does not reach the fallback: %q %v", text, err)
665		}
666		spent := (1 << 20) - full.remaining
667		t.Logf("budget spent: %d bytes", spent)
668	
669		// The bound is absolute, derived from the fixture rather than from the
670		// measurement: a budget computed off the observed spend scales with the
671		// bug and can never fail. The CMap body is the dominant stream, so one
672		// honest pass costs a little over its size and a second decode costs about
673		// that again. Measured: 7,256 bytes with the skip, 14,456 without.
674		cmapBytes := int64(400 * len("begincmap endcmap\n"))
675		if ceiling := cmapBytes + cmapBytes/2; spent > ceiling {
676			t.Fatalf("decoding spent %d bytes against a ceiling of %d; the CMap stream is being decoded twice", spent, ceiling)
677		}
678	}
